import { describe, expect, test } from "bun:test"
import { TICK_DT } from "../shared/clock"
import { CoopSim, type SurvivorSlot } from "../shared/coop-sim"
import type { InteractionsState } from "../shared/interactions/index"
import { furnitureSites, FURNITURE_KINDS, furnRect, type FurnitureKind } from "../shared/interactions/furniture"
import { haulStoreId } from "../shared/interactions/drag"
import { DEFAULT_INTERACTIONS_TUNING, type InteractionsTuning } from "../shared/interactions/tuning"
import { DEFAULT_DEATH_TUNING } from "../shared/death/rules"
import { solidRects } from "../shared/map"
import type { Command } from "../shared/session"
import { createBotWorldView } from "../shared/survivor-bot"

const idle = (aim = 0): Command => ({ mx: 0, my: 0, aim, interact: false })
const ticks = (seconds: number) => Math.ceil(seconds / TICK_DT)

function room(ids: string[], tuning: Partial<InteractionsTuning> = {}) {
  const sim = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
  sim.hour = 12
  for (const [i, id] of ids.entries()) sim.addSurvivor(id, i)
  sim.rebuildSolids()
  const settings = { interactions: { ...DEFAULT_INTERACTIONS_TUNING, ...tuning }, death: { ...DEFAULT_DEATH_TUNING, deathMode: 1 } } as never
  const tick = (cmds: Partial<Record<string, Partial<Command>>> = {}, n = 1) => {
    for (let k = 0; k < n; k++) {
      for (const s of sim.slots) sim.stepSurvivor(s, { ...idle(s.survivor.aim), ...cmds[s.id] }, TICK_DT, settings)
      sim.stepWorld(TICK_DT, 0, settings)
    }
  }
  const state = () => sim.getFeatureState<InteractionsState>("interactions")!
  const pieces = () => [...sim.progression.ledger.stores.values()].filter((s) => s.id.startsWith("furn:"))
  const place = (slot: SurvivorSlot, x: number, y: number, aim: number) => Object.assign(slot.survivor, { x, y, aim })
  tick()
  return { sim, tick, state, pieces, place, slot: (id: string) => sim.slot(id)! }
}

/** Puts a loose piece of `kind` at `(x, y)` (replacing whatever the house had as its first). */
function putPiece(sim: CoopSim, kind: FurnitureKind, x: number, y: number) {
  const st = [...sim.progression.ledger.stores.values()].find((s) => s.id.startsWith("furn:ash:"))!
  st.at = { x, y }
  st.counts = { k: FURNITURE_KINDS.indexOf(kind), yaw: 0 }
  st.rev = ++sim.progression.ledger.rev
  return st
}

describe("loose furniture", () => {
  test("houses have loose pieces on open floor, seeded from the town alone", () => {
    const sim = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
    const solids = solidRects(sim.town)
    const houses = sim.town.buildings.filter((b) => b.kind === "house")
    const sites = houses.flatMap((b) => furnitureSites(sim.town, b, 2, solids))
    expect(sites.length).toBeGreaterThan(houses.length)
    expect(houses.flatMap((b) => furnitureSites(sim.town, b, 2, solids))).toEqual(sites)
    for (const s of sites) {
      const r = furnRect(s.x, s.y, s.kind, s.yaw)
      expect(solids.some((o) => r[0] < o[2] && r[2] > o[0] && r[1] < o[3] && r[3] > o[1])).toBe(false)
    }
    expect(houses.flatMap((b) => furnitureSites(sim.town, b, 0, solids))).toEqual([])
  })

  test("E takes hold of a dresser: it goes in front, slows you, and E sets it down", () => {
    const { sim, tick, pieces, place, slot } = room(["ann"])
    expect(pieces().length).toBeGreaterThan(0)
    const st = putPiece(sim, "dresser", 27, 29)
    const ann = slot("ann")
    place(ann, 27, 30, -Math.PI / 2)
    tick()
    expect(ann.prompt?.kind).toBe("furniture")
    expect(ann.prompt?.primary.label).toBe("Drag")
    tick({ ann: { interact: true, aim: -Math.PI / 2 } })
    expect(st.counts.drag).toBe(1)
    expect(st.owner).toBe("ann")
    // Walk east for a second: slower than walking free, the dresser kept in front.
    const x0 = ann.survivor.x
    tick({ ann: { mx: 1, my: 0, aim: 0 } }, ticks(1))
    const dragged = ann.survivor.x - x0
    expect(st.at!.x).toBeGreaterThan(ann.survivor.x + 0.4)
    tick({ ann: { interact: true, aim: 0 } })
    expect(st.counts.drag).toBe(0)
    // Free again, out on the street: a full walking pace.
    place(ann, 44, 44, 0)
    tick({ ann: { mx: 1, my: 0, aim: 0 } }, ticks(1))
    expect(ann.survivor.x - 44).toBeGreaterThan(dragged * 1.4)
  })

  test("set down against a door it braces it: the door shuts and the crowd counts it barricaded until bashed through", () => {
    const { sim, tick, place, slot, state } = room(["ann"])
    const door = sim.town.doors.find((d) => d.id === "ash-front")!
    const cx = (door.rect[0] + door.rect[2]) / 2
    const st = putPiece(sim, "dresser", cx, door.rect[1] - 1.5)
    const ann = slot("ann")
    place(ann, cx, door.rect[1] - 2.3, Math.PI / 2)
    tick({ ann: { interact: true, aim: Math.PI / 2 } })
    expect(st.counts.drag).toBe(1)
    tick({ ann: { mx: 0, my: 1, aim: Math.PI / 2 } }, ticks(0.6))
    tick()
    expect(ann.prompt?.primary.label).toBe("Brace")
    door.open = true
    tick({ ann: { interact: true, aim: Math.PI / 2 } })
    expect(st.counts.br).toBe(1)
    expect(door.open).toBe(false)
    const holds = sim.ai.portalHolds!
    expect(holds.held(door.id)).toBe(true)
    sim.ai.rebuildTopology(sim.town)
    expect((sim.ai as unknown as { portals: { id: string; barricadePlanks: number }[] }).portals.find((p) => p.id === door.id)!.barricadePlanks).toBe(1)
    expect(state().drag.braced[st.id]).toBe(door.id)
    // Bashed: it holds while it has hit points, then is shoved into the room and falls over.
    expect(holds.absorb(door.id, 100, sim.time)).toBe(0)
    expect(holds.held(door.id)).toBe(true)
    holds.absorb(door.id, 1000, sim.time)
    expect(holds.held(door.id)).toBe(false)
    expect(st.counts.down).toBe(1)
    expect(st.at!.y).toBeLessThan(door.rect[1] - 0.6)
  })

  test("with readable breaches on, the dead's bashes land on a braced piece and topple it", () => {
    const { sim, tick, place, slot } = room(["ann"])
    const door = sim.town.doors.find((d) => d.id === "ash-front")!
    const cx = (door.rect[0] + door.rect[2]) / 2
    const st = putPiece(sim, "chair", cx, door.rect[1] - 1.2)
    const ann = slot("ann")
    place(ann, cx, door.rect[1] - 2, Math.PI / 2)
    tick({ ann: { interact: true, aim: Math.PI / 2 } })
    tick({ ann: { interact: true, aim: Math.PI / 2 } })
    expect(st.counts.br).toBe(1)
    const rules = sim.ai.bashRules!
    expect(rules).toBeTruthy()
    const bash = (damage: number) => rules.apply(sim.town, sim.ai.portalStates, [{ agentId: 1, portalId: door.id, portalKind: "door", x: cx, y: door.rect[3] + 0.5, damage }], sim.time, [])
    bash(20)
    expect(st.counts.br).toBe(1)
    expect(sim.ai.portalStates.get(door.id)!.integrity).toBe(100)
    expect(bash(500)).toBe(true)
    expect(st.counts.down).toBe(1)
  })

  test("bots see every piece no one drags as an obstacle; closets keep their floor clear", () => {
    const { sim, tick, pieces, slot } = room(["ann"])
    const view = () => createBotWorldView(sim).obstacles ?? []
    expect(view().length).toBe(pieces().length)
    const st = putPiece(sim, "chair", 27, 29)
    const ann = slot("ann")
    Object.assign(ann.survivor, { x: 27, y: 30, aim: -Math.PI / 2 })
    tick()
    tick({ ann: { interact: true, aim: -Math.PI / 2 } })
    expect(st.counts.drag).toBe(1)
    expect(view().length).toBe(pieces().length - 1)
    for (const c of sim.town.props.filter((p) => p.kind === "closet")) {
      const front: [number, number, number, number] = [c.x - 0.6, c.y + 0.3, c.x + 0.6, c.y + 2]
      for (const r of view()) expect(r[0] < front[2] && r[2] > front[0] && r[1] < front[3] && r[3] > front[1]).toBe(false)
    }
  })

  test("Today (furniture off): no loose pieces are put out", () => {
    const { pieces } = room(["ann"], { furniture: 0 })
    expect(pieces().length).toBe(0)
  })
})

describe("hauling a downed teammate", () => {
  test("tap E drags them along behind you, slowly; tap again lets go; hold still revives", () => {
    const { sim, tick, place, slot } = room(["ann", "bo"])
    const ann = slot("ann")
    const bo = slot("bo")
    place(ann, 44, 44, 0)
    place(bo, 45, 44, 0)
    bo.survivor.health = 0
    tick({}, 2)
    expect(ann.prompt?.kind).toBe("downed")
    expect(ann.prompt?.primary.label).toBe("Drag")
    tick({ ann: { interact: true, aim: Math.PI } })
    tick({ ann: { aim: Math.PI } }, 2)
    expect(sim.progression.ledger.store(haulStoreId(ann.index))?.counts.who).toBe(bo.index + 1)
    const x0 = ann.survivor.x
    tick({ ann: { mx: -1, my: 0, aim: Math.PI } }, ticks(1))
    expect(x0 - ann.survivor.x).toBeLessThan(3)
    expect(x0 - ann.survivor.x).toBeGreaterThan(0.8)
    expect(bo.survivor.x).toBeGreaterThan(ann.survivor.x + 0.4)
    expect(Math.abs(bo.survivor.x - ann.survivor.x)).toBeLessThan(1.4)
    tick({ ann: { interact: true, aim: 0 } })
    tick({}, 2)
    expect(sim.progression.ledger.store(haulStoreId(ann.index))?.counts.who).toBe(0)
  })
})

import { describe, expect, test } from "bun:test"
import { TICK_DT } from "../shared/clock"
import { CoopSim } from "../shared/coop-sim"
import { HOLD_DURATION } from "../shared/interact"
import { freshWear, type BreachState } from "../shared/breach/rules"
import { BOARDS_KIND } from "../shared/interactions/boards"
import { DEFAULT_INTERACTIONS_TUNING, type InteractionsTuning } from "../shared/interactions/tuning"
import { DEFAULT_PROGRESSION_TUNING } from "../shared/progression/tuning"
import type { Command } from "../shared/session"

const idle = (aim = 0): Command => ({ mx: 0, my: 0, aim, interact: false })
const ticks = (seconds: number) => Math.ceil(seconds / TICK_DT)
const T = DEFAULT_PROGRESSION_TUNING

/** Ann just outside Ash's front door, facing it, with `planks` in her belt. */
function atDoor(planks: number, tuning: Partial<InteractionsTuning> = {}) {
  const sim = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
  sim.hour = 12
  sim.addSurvivor("ann", 0)
  sim.rebuildSolids()
  const settings = { interactions: { ...DEFAULT_INTERACTIONS_TUNING, ...tuning } } as never
  const ann = sim.slot("ann")!
  const door = sim.town.doors.find((d) => d.id === "ash-front")!
  door.open = false
  const aim = Math.PI / 2
  Object.assign(ann.survivor, { x: (door.rect[0] + door.rect[2]) / 2, y: door.rect[1] - 1, aim })
  const ledger = sim.progression.ledger
  const have = ledger.count("ann", "plank")
  if (planks > have) ledger.apply({ kind: "grant", actor: "ann", item: "plank", count: planks - have })
  const tick = (cmd: Partial<Command> = {}, n = 1) => {
    for (let k = 0; k < n; k++) {
      sim.stepSurvivor(ann, { ...idle(aim), ...cmd }, TICK_DT, settings)
      sim.stepWorld(TICK_DT, 0, settings)
    }
  }
  tick()
  return { sim, ann, door, tick, planks: () => sim.ai.getBarricadePlanks(door.id), belt: () => ledger.count("ann", "plank") }
}

describe("boarding up", () => {
  test("one B keeps nailing boards until the door is full", () => {
    const { tick, planks, belt } = atDoor(4)
    tick({ barricade: true })
    tick({}, ticks(T.barricadeTime * 3 + 1))
    expect(planks()).toBe(3)
    expect(belt()).toBe(1)
  })

  test("it stops when the planks run out", () => {
    const { tick, planks, belt } = atDoor(2)
    tick({ barricade: true })
    tick({}, ticks(T.barricadeTime * 3 + 1))
    expect(planks()).toBe(2)
    expect(belt()).toBe(0)
  })

  test("Today (chain off): one board per B", () => {
    const { tick, planks } = atDoor(4, { boardChain: 0 })
    tick({ barricade: true })
    tick({}, ticks(T.barricadeTime * 3 + 1))
    expect(planks()).toBe(1)
  })
})

describe("prying a board off", () => {
  test("hold E at a boarded door: one board comes off and goes back in the belt; the tap is still refused", () => {
    const { sim, ann, door, tick, planks, belt } = atDoor(2, { boardChain: 0 })
    sim.ai.addBarricadePlank(door.id)
    sim.ai.addBarricadePlank(door.id)
    tick()
    expect(ann.prompt?.secondary?.label).toBe("Pry off a board")
    expect(ann.prompt?.secondary?.hold).toBe(true)
    tick({ interact: true, interactHeld: true })
    expect(door.open).toBe(false)
    expect(ann.survivor.lootMessage).toContain("hold E")
    tick({ interactHeld: true }, ticks(HOLD_DURATION + 0.05))
    expect(ann.survivor.channel?.kind).toBe("unboard")
    expect(sim.ai.noiseBus.snapshot().events.some((e: { kind: string }) => e.kind === "barricade")).toBe(true)
    tick({}, ticks(T.unboardTime + 0.2))
    expect(planks()).toBe(1)
    expect(belt()).toBe(3)
  })

  test("a boarded window's hold pries too, without peeking first", () => {
    const { sim, ann, tick } = atDoor(0)
    const win = sim.town.windows.find((w) => w.id.startsWith("ash"))!
    sim.ai.addBarricadePlank(win.id)
    const aim = -Math.PI / 2
    const cx = (win.rect[0] + win.rect[2]) / 2
    const cy = (win.rect[1] + win.rect[3]) / 2
    // Stand off the window's long side, facing it.
    const horizontal = win.rect[2] - win.rect[0] > win.rect[3] - win.rect[1]
    Object.assign(ann.survivor, horizontal ? { x: cx, y: cy + 1, aim } : { x: cx + 1, y: cy, aim: Math.PI })
    const face = ann.survivor.aim
    tick({ aim: face })
    expect(ann.prompt?.id).toBe(win.id)
    expect(ann.prompt?.secondary?.label).toBe("Pry off a board")
    tick({ aim: face, interact: true, interactHeld: true })
    tick({ aim: face, interactHeld: true }, ticks(HOLD_DURATION + 0.05))
    expect(ann.survivor.peekingWindowId).toBe(null)
    tick({ aim: face }, ticks(T.unboardTime + 0.2))
    expect(sim.ai.getBarricadePlanks(win.id)).toBe(0)
  })

  test("a doorway whose door the dead tore off, boarded since: hold E still pries, a tap does not", () => {
    const { sim, ann, door, tick, planks } = atDoor(0, { boardChain: 0 })
    tick()
    const breach = sim.getFeatureState<BreachState>("breach")!
    expect(breach.on).toBe(true)
    breach.portals[door.id] = { ...freshWear(), broken: true }
    door.open = true
    sim.ai.addBarricadePlank(door.id)
    sim.ai.addBarricadePlank(door.id)
    tick()
    expect(ann.prompt?.kind).toBe(BOARDS_KIND)
    tick({ interact: true })
    tick({}, ticks(T.unboardTime + 0.2))
    expect(planks()).toBe(2)
    tick({ interact: true, interactHeld: true })
    tick({ interactHeld: true }, ticks(HOLD_DURATION + 0.05))
    tick({}, ticks(T.unboardTime + 0.2))
    expect(planks()).toBe(1)
  })

  test("Today (pry off): a boarded door's hold does not pry", () => {
    const { sim, ann, door, tick, planks } = atDoor(0, { pryBoards: 0 })
    sim.ai.addBarricadePlank(door.id)
    tick()
    expect(ann.prompt?.secondary?.label).not.toBe("Pry off a board")
    tick({ interact: true, interactHeld: true })
    tick({ interactHeld: true }, ticks(HOLD_DURATION + T.unboardTime + 0.3))
    expect(planks()).toBe(1)
  })
})

import { describe, expect, test } from "bun:test"
import { TICK_DT } from "../shared/clock"
import { CoopSim, type SurvivorSlot } from "../shared/coop-sim"
import { throwableSite } from "../shared/interactions/toss-sites"
import { OUT_BONK, OUT_HIT, planToss, THROWABLES, throwPower, tossAt } from "../shared/interactions/throwables"
import { DEFAULT_INTERACTIONS_TUNING, type InteractionsTuning } from "../shared/interactions/tuning"
import type { Command } from "../shared/session"

const idle = (aim = 0): Command => ({ mx: 0, my: 0, aim, interact: false })
const ticks = (seconds: number) => Math.ceil(seconds / TICK_DT)

function room(pose: { x: number; y: number; aim: number }, tuning: Partial<InteractionsTuning> = {}) {
  const sim = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
  sim.hour = 22
  Object.assign(sim.addSurvivor("ann", 0).survivor, pose)
  sim.rebuildSolids()
  const settings = { interactions: { ...DEFAULT_INTERACTIONS_TUNING, ...tuning } } as never
  const tick = (cmd: Partial<Command> = {}, n = 1) => {
    for (let k = 0; k < n; k++) {
      for (const s of sim.slots) sim.stepSurvivor(s, { ...idle(s.survivor.aim), ...cmd }, TICK_DT, settings)
      sim.stepWorld(TICK_DT, 0, settings)
    }
  }
  const heard: { kind: string; radius: number; x: number; y: number }[] = []
  const emit = sim.ai.emitNoise.bind(sim.ai)
  sim.ai.emitNoise = (x, y, radius, kind, ...rest) => {
    heard.push({ kind, radius, x, y })
    return emit(x, y, radius, kind, ...rest)
  }
  const ledger = sim.progression.ledger
  const slot = sim.slot("ann")!
  const hold = (item: string, count = 1) => {
    ledger.apply({ kind: "grant", actor: slot.id, item, count })
    const i = sim.progression.hotbar(slot.id)?.slots.findIndex((s) => s?.item === item) ?? -1
    if (i >= 0) ledger.apply({ kind: "select", actor: slot.id, slot: i })
    sim.progression.project(slot)
  }
  const zombie = (x: number, y: number) => {
    const z = sim.ai.spawnZombie(sim.town, x, y, "wander")
    z.speedScale = 0
    return z
  }
  const throwFor = (seconds: number) => {
    tick({ fire: true, fireHeld: true })
    tick({ fireHeld: true }, Math.max(0, ticks(seconds) - 1))
    tick({ fireHeld: false })
  }
  const drops = () => [...ledger.stores.values()].filter((s) => s.id.startsWith("drop:t:"))
  return { sim, tick, ledger, slot, hold, zombie, throwFor, drops, noises: (kind: string) => heard.filter((e) => e.kind === kind) }
}

const street = { x: 30, y: 46, aim: 0 }

describe("throwables", () => {
  test("holding longer throws further; a tap is a short lob", () => {
    const t = DEFAULT_INTERACTIONS_TUNING
    expect(throwPower(0, t)).toBeCloseTo(t.throwTap)
    expect(throwPower(t.throwWindup, t)).toBe(1)
    const tap = planToss(0, 0, 0, throwPower(0, t), THROWABLES.baseball, 1, [], [], [])
    const full = planToss(0, 0, 0, 1, THROWABLES.baseball, 1, [], [], [])
    expect(full.ix).toBeGreaterThan(tap.ix * 2.5)
  })

  test("a baseball winds up, flies, bonks one of the dead down and lies there to be picked up again", () => {
    const { sim, tick, hold, zombie, throwFor, drops, ledger, slot } = room(street)
    hold("baseball")
    const z = zombie(34.5, 46)
    const hp = z.hp
    // A flat throw at a head six metres off: a quick tap, which flies at head height.
    throwFor(0)
    expect(ledger.count(slot.id, "baseball")).toBe(0)
    const st = ledger.store("toss:0")!
    expect(st.counts.out! & OUT_HIT).toBeTruthy()
    expect(st.counts.out! & OUT_BONK).toBeTruthy()
    tick({}, ticks(1.4))
    expect(z.hp).toBeLessThan(hp)
    expect(["knockdown", "dead"]).toContain(z.state)
    expect(drops().length).toBe(1)
    expect(sim.progression.contents(drops()[0]!.id)[0]?.item).toBe("baseball")
  })

  test("a can lobbed long flies over the heads in the middle and is heard where it lands", () => {
    const { tick, hold, zombie, throwFor, ledger, noises } = room(street)
    hold("tin-can")
    const z = zombie(36, 46)
    throwFor(1)
    tick({}, ticks(1.5))
    expect(z.state).not.toBe("stagger")
    const st = ledger.store("toss:0")!
    expect(st.counts.out! & OUT_HIT).toBe(0)
    const heard = noises("cans")
    expect(heard.length).toBe(1)
    expect(heard[0]!.x).toBeGreaterThan(40)
  })

  test("a bottle shatters into glass where it lands and leaves nothing to pick up", () => {
    const { tick, hold, throwFor, ledger, drops, noises } = room(street)
    hold("bottle")
    throwFor(0.4)
    tick({}, ticks(1.5))
    expect(noises("glass").length).toBe(1)
    expect([...ledger.stores.keys()].some((id) => id.startsWith("glass:"))).toBe(true)
    expect(drops().length).toBe(0)
  })

  test("Today (throwables off): a bottle is the old instant fixed-range throw", () => {
    const { tick, hold, ledger, noises } = room(street, { throwables: 0 })
    tick()
    hold("bottle")
    tick({ fire: true, fireHeld: true })
    expect(noises("glass").length).toBe(1)
    expect(ledger.store("toss:0")).toBeUndefined()
  })

  test("a brick goes through a shut window, breaking it", () => {
    const { sim, tick, hold, throwFor, noises } = room(street)
    const w = sim.town.windows.find((x) => !x.open && !x.boarded)!
    const cx = (w.rect[0] + w.rect[2]) / 2
    const cy = (w.rect[1] + w.rect[3]) / 2
    const horizontal = w.rect[2] - w.rect[0] > w.rect[3] - w.rect[1]
    const p = sim.slot("ann")!.survivor
    // Stand four metres off the glass, facing it, on whichever side is open ground.
    const nx = horizontal ? 0 : 1
    const ny = horizontal ? 1 : 0
    const side = sim.solids.some((r) => cx + nx * 4 > r[0] && cx + nx * 4 < r[2] && cy + ny * 4 > r[1] && cy + ny * 4 < r[3]) ? -1 : 1
    p.x = cx + nx * 4 * side
    p.y = cy + ny * 4 * side
    p.aim = Math.atan2(cy - p.y, cx - p.x)
    hold("brick")
    throwFor(0.75)
    tick({ aim: p.aim }, ticks(1.5))
    expect(w.open).toBe(true)
    expect(noises("glass").length).toBeGreaterThan(0)
  })

  test("the flight reads the same on every seat: from the hand, up the arc, down to rest", () => {
    const { sim, hold, throwFor, ledger } = room(street)
    hold("rock")
    throwFor(0.75)
    const st = ledger.store("toss:0")!
    const t0 = st.counts.t! / 10
    const start = tossAt(st, t0)!
    const mid = tossAt(st, t0 + st.counts.fl! / 20)!
    const end = tossAt(st, t0 + 5)!
    expect(start.x).toBeCloseTo(30.35, 1)
    expect(mid.h).toBeGreaterThan(start.h)
    expect(end.phase).toBe(2)
    expect(end.x).toBeCloseTo(st.at!.x, 5)
  })

  test("some houses have one lying about, seeded from the town alone", () => {
    const sim = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
    const houses = sim.town.buildings.filter((b) => b.kind === "house")
    const sites = houses.map((b) => throwableSite(sim.town, b, 1)).filter(Boolean)
    expect(sites.length).toBeGreaterThan(0)
    expect(houses.map((b) => throwableSite(sim.town, b, 1))).toEqual(houses.map((b) => throwableSite(sim.town, b, 1)))
    expect(houses.every((b) => throwableSite(sim.town, b, 0) === null)).toBe(true)
  })
})

export type { SurvivorSlot }

import { describe, expect, test } from "bun:test"
import { TICK_DT } from "../shared/clock"
import { CoopSim, type SurvivorSlot } from "../shared/coop-sim"
import { bodySites, DEFAULT_BODIES_TUNING, type BodiesTuning } from "../shared/bodies/bodies"
import { DEFAULT_DOG_TUNING, dogSites, dogState, type DogTuning } from "../shared/dogs/dogs"
import { DEFAULT_FLARE_TUNING, flareBurning, type FlareTuning } from "../shared/flares/flares"
import { pullToward } from "../shared/flares/runtime"
import { DEFAULT_LIGHTS_TUNING, lampHeads, lampOnShot, lampStoreId, porchSwitch, type LightsTuning } from "../shared/lights-out/lights"
import { samplePointLightLevel } from "../shared/ai"
import type { Lamp } from "../shared/map"
import { sightRects } from "../shared/map"
import type { Command } from "../shared/session"

type Tuning = Partial<LightsTuning & FlareTuning & BodiesTuning & DogTuning>
type Pose = { x: number; y: number; aim: number }

const idle = (aim = 0): Command => ({ mx: 0, my: 0, aim, interact: false })
const ticks = (seconds: number) => Math.ceil(seconds / TICK_DT) + 2

function room(poses: Record<string, Pose>, tuning: Tuning = {}, zombies = 0) {
  const sim = new CoopSim(7, 7, 0.22, { zombieCount: zombies })
  sim.hour = 22
  for (const [i, [id, pose]] of Object.entries(poses).entries()) Object.assign(sim.addSurvivor(id, i).survivor, pose)
  sim.rebuildSolids()
  const settings = { discovery: { ...DEFAULT_LIGHTS_TUNING, ...DEFAULT_FLARE_TUNING, ...DEFAULT_BODIES_TUNING, ...DEFAULT_DOG_TUNING, ...tuning } } as never
  const tick = (cmds: Partial<Record<string, Partial<Command>>> = {}, n = 1) => {
    for (let k = 0; k < n; k++) {
      for (const s of sim.slots) sim.stepSurvivor(s, { ...idle(s.survivor.aim), ...cmds[s.id] }, TICK_DT, settings)
      sim.stepWorld(TICK_DT, 0, settings)
    }
  }
  const heard: { kind: string; radius: number }[] = []
  const emit = sim.ai.emitNoise.bind(sim.ai)
  sim.ai.emitNoise = (x, y, radius, kind, ...rest) => {
    heard.push({ kind, radius })
    return emit(x, y, radius, kind, ...rest)
  }
  const ledger = sim.progression.ledger
  const hold = (slot: SurvivorSlot, item: string, count = 1) => {
    if (count) ledger.apply({ kind: "grant", actor: slot.id, item, count })
    const i = sim.progression.hotbar(slot.id)?.slots.findIndex((s) => s?.item === item) ?? -1
    if (i >= 0) ledger.apply({ kind: "select", actor: slot.id, slot: i })
    sim.progression.project(slot)
  }
  return { sim, tick, ledger, slot: (id: string) => sim.slot(id)!, hold, noises: (kind: string) => heard.filter((e) => e.kind === kind) }
}

/** The street lamp nearest Ash's front, and Ash's porch light. */
function ashLamps(sim: CoopSim): { street: Lamp; porch: Lamp } {
  const ash = sim.town.buildings.find((b) => b.id === "ash")!
  const cx = (ash.rect[0] + ash.rect[2]) / 2
  const d = (l: Lamp) => Math.hypot(l.x - cx, l.y - ash.rect[3])
  const of = (kind: string) => sim.town.lamps.filter((l) => l.kind === kind).sort((a, b) => d(a) - d(b))[0]!
  return { street: of("street"), porch: of("porch") }
}

describe("Lights Out", () => {
  test("a pistol shot past a street lamp's head puts it out for good: glass on the ground, a pop, and darker under it", () => {
    const probe = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
    const { street } = ashLamps(probe)
    const head = lampHeads(street)[0]!
    const from = { x: head.x - 3, y: head.y + 3 }
    const { sim, tick, ledger, slot, hold, noises } = room({ ann: { ...from, aim: Math.atan2(head.y - from.y, head.x - from.x) } })
    hold(slot("ann"), "pistol", 0)
    tick()
    const lamp = sim.town.lamps.find((l) => lampStoreId(l) === lampStoreId(street))!
    const lit = samplePointLightLevel(sim.town, sim.hour, lamp.x + 0.5, lamp.y + 0.3)
    expect(lamp.power).toBeGreaterThan(0)
    tick({ ann: { fire: true } })
    tick()
    expect(ledger.store(lampStoreId(street))?.counts.broken).toBe(1)
    expect(ledger.store(`glass:${lampStoreId(street)}`)).toBeDefined()
    expect(noises("glass").length).toBe(1)
    expect(lamp.power).toBe(0)
    expect(samplePointLightLevel(sim.town, sim.hour, lamp.x + 0.5, lamp.y + 0.3)).toBeLessThan(lit)
    // A second shot finds nothing left to break.
    tick({}, ticks(0.6))
    tick({ ann: { fire: true } })
    tick()
    expect(noises("glass").length).toBe(1)
  })

  test("a shot stops at what it hits: a lamp behind a wall is safe", () => {
    const sim = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
    const { street } = ashLamps(sim)
    const head = lampHeads(street)[0]!
    expect(lampOnShot(sim.town, head.x - 4, head.y, head.x + 4, head.y, 0.5, () => false)?.lamp).toBe(street)
    expect(lampOnShot(sim.town, head.x - 4, head.y, head.x - 2, head.y, 0.5, () => false)).toBeNull()
    expect(lampOnShot(sim.town, head.x - 4, head.y + 2, head.x + 4, head.y + 2, 0.5, () => false)).toBeNull()
  })

  test("a porch light's switch: E on the step switches it off and on again; facing the door keeps the door's prompt", () => {
    const probe = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
    const sw = porchSwitch(ashLamps(probe).porch)
    const { sim, tick, ledger, slot } = room({ ann: { x: sw.x - 0.1, y: sw.y + 0.7, aim: -Math.PI / 2 } })
    tick()
    const porch = sim.town.lamps.find((l) => lampStoreId(l) === lampStoreId(ashLamps(sim).porch))!
    const power = porch.power
    expect(slot("ann").prompt?.kind).toBe("lamp")
    expect(slot("ann").prompt?.primary.label).toBe("Switch off")
    tick({ ann: { interact: true } })
    expect(ledger.store(lampStoreId(porch))?.counts.off).toBe(1)
    expect(porch.power).toBe(0)
    tick()
    expect(slot("ann").prompt?.primary.label).toBe("Switch on")
    tick({ ann: { interact: true } })
    expect(ledger.store(lampStoreId(porch))?.counts.off).toBe(0)
    expect(porch.power).toBe(power)
    // Turned to face the front door, the door has the prompt.
    const door = sim.town.doors.find((d) => d.id === "ash-front")!
    const dx = (door.rect[0] + door.rect[2]) / 2
    const dy = (door.rect[1] + door.rect[3]) / 2
    Object.assign(slot("ann").survivor, { x: dx, y: dy + 0.9, aim: -Math.PI / 2 })
    tick()
    expect(slot("ann").prompt?.kind).toBe("door")
  })

  test("a dark lamp stays dark in a fork of the sim", () => {
    const { sim, ledger } = room({ ann: { x: 30, y: 40, aim: 0 } })
    const { street } = ashLamps(sim)
    ledger.createStore({ id: lampStoreId(street), mode: "counters", scope: "shared", at: { x: street.x, y: street.y }, initial: { broken: 1, off: 0 } })
    sim.stepWorld(TICK_DT, 0, {} as never)
    const fork = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
    fork.restoreSnapshot(sim.toSnapshot())
    fork.stepWorld(TICK_DT, 0, {} as never)
    expect(fork.town.lamps.find((l) => lampStoreId(l) === lampStoreId(street))!.power).toBe(0)
  })
})

describe("road flares", () => {
  test("fire with a flare in hand throws it: one fewer, burning where it lands, then out and gone", () => {
    const { sim, tick, ledger, slot, hold } = room({ ann: { x: 30, y: 46, aim: 0 } }, { flareSeconds: 2 })
    hold(slot("ann"), "flare", 2)
    tick({ ann: { fire: true } })
    const flares = [...ledger.stores.values()].filter((s) => s.id.startsWith("flare:"))
    expect(flares.length).toBe(1)
    expect(ledger.count("ann", "flare")).toBe(1)
    expect(flareBurning(flares[0], sim.time)).toBe(true)
    expect(flares[0]!.at!.x).toBeGreaterThan(31)
    expect(slot("ann").survivor.fireCooldown).toBe(0)
    tick({}, ticks(2.2))
    expect([...ledger.stores.values()].some((s) => s.id.startsWith("flare:"))).toBe(false)
  })

  test("the dead who can see a burning flare go and stand round it; the ones already after a survivor do not", () => {
    const { sim, tick, slot, hold } = room({ ann: { x: 30, y: 46, aim: 0 } }, { flareThrow: 6 })
    const near = sim.ai.spawnZombie(sim.town, 44, 46, "wander", 0)
    // Torch off, so it is the flare they see and not the survivor.
    slot("ann").survivor.flashlightOn = false
    hold(slot("ann"), "flare", 1)
    tick({ ann: { fire: true } })
    tick({}, ticks(0.6))
    expect(near.targetKind).toBe("light")
    expect(near.state).toBe("investigate")
    expect(Math.hypot(near.targetX - 36, near.targetY - 46)).toBeLessThan(2.5)
    // One already after a survivor is not turned.
    const chasing = sim.ai.spawnZombie(sim.town, 40, 47, "chase")
    pullToward(sim, sightRects(sim.town), 36, 46, 16)
    expect(chasing.targetKind).not.toBe("light")
  })

  test("a flare's light does not go through walls", () => {
    const sim = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
    const ash = sim.town.buildings.find((b) => b.id === "ash")!
    const inside = sim.ai.spawnZombie(sim.town, (ash.rect[0] + ash.rect[2]) / 2, (ash.rect[1] + ash.rect[3]) / 2, "wander")
    for (const d of sim.town.doors) d.open = false
    const blockers = sightRects(sim.town)
    const x = (ash.rect[0] + ash.rect[2]) / 2
    const y = ash.rect[3] + 3
    expect(Math.hypot(inside.x - x, inside.y - y)).toBeLessThan(16)
    pullToward(sim, blockers, x, y, 16)
    expect(inside.targetKind).not.toBe("light")
  })
})

describe("bodies to search", () => {
  test("placed from the seed, the same in two rooms; the start district has one by Ash's porch", () => {
    const a = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
    const b = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
    expect(bodySites(a.town)).toEqual(bodySites(b.town))
    expect(bodySites(a.town).map((s) => s.key)).toContain("porch:ash")
  })

  test("E searches a body (a quiet channel), then what it carried is on show and E takes it", () => {
    const probe = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
    const body = bodySites(probe.town).find((b) => b.key === "porch:ash")!
    const { tick, ledger, slot, noises } = room({ ann: { x: body.x - 0.4, y: body.y + 0.8, aim: Math.atan2(-0.8, 0.4) } }, { bodyRiseChance: 0 })
    tick()
    expect(slot("ann").prompt?.kind).toBe("body")
    expect(slot("ann").prompt?.primary.id).toBe("search")
    tick({ ann: { interact: true } })
    tick({}, ticks(DEFAULT_BODIES_TUNING.bodySearchTime))
    expect(ledger.store(body.id)?.revealed).toBe(true)
    tick()
    expect(slot("ann").prompt?.primary.id).toBe("take")
    const carried = ledger.store(body.id)!.slots.filter((s) => s !== null).length
    expect(carried).toBeGreaterThan(0)
    tick({ ann: { interact: true } })
    expect(ledger.store(body.id)!.slots.filter((s) => s !== null).length).toBeLessThan(carried)
  })

  test("one that is not quite dead rises as you reach for it, comes for you, and leaves what it carried", () => {
    const probe = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
    const body = bodySites(probe.town).find((b) => b.key === "porch:ash")!
    const { sim, tick, ledger, slot } = room({ ann: { x: body.x - 0.4, y: body.y + 0.8, aim: Math.atan2(-0.8, 0.4) } }, { bodyRiseChance: 1 })
    tick()
    const before = sim.ai.agents.filter((a) => a.state !== "dead").length
    tick({ ann: { interact: true } })
    expect(ledger.store(body.id)?.counts.rise).toBeGreaterThan(0)
    tick()
    expect(slot("ann").prompt?.kind).not.toBe("body")
    tick({}, ticks(DEFAULT_BODIES_TUNING.bodyRiseDelay))
    expect(ledger.store(body.id)?.counts.risen).toBe(1)
    const risen = sim.ai.agents.filter((a) => a.state !== "dead")
    expect(risen.length).toBe(before + 1)
    expect(Math.hypot(risen.at(-1)!.targetX - slot("ann").survivor.x, risen.at(-1)!.targetY - slot("ann").survivor.y)).toBeLessThan(1)
    expect(ledger.store(`drop:body:${body.key}`)?.slots.some((s) => s !== null)).toBe(true)
  })

  test("the vignette's survivor never rises", () => {
    const sim = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
    for (const b of bodySites(sim.town)) if (b.vignette) expect(b.riseRoll).toBe(1)
  })
})

describe("chained dogs", () => {
  const probe = new CoopSim(7, 7, 0.22, { zombieCount: 0 })
  const dog = dogSites(probe.town).find((d) => d.buildingId === "elm")!

  test("Elm keeps one in its side yard, out of every building, the same in two rooms", () => {
    expect(dog).toBeDefined()
    expect(dogSites(new CoopSim(7, 7, 0.22, { zombieCount: 0 }).town)).toEqual(dogSites(probe.town))
    for (const b of probe.town.buildings) {
      const [x0, y0, x1, y1] = b.rect
      expect(dog.x > x0 && dog.x < x1 && dog.y > y0 && dog.y < y1).toBe(false)
    }
  })

  test("it barks at a survivor who comes near, on a beat; feed it and it hushes and knows them", () => {
    const { sim, tick, ledger, slot, hold, noises } = room({ ann: { x: dog.x + dog.chain + 0.6, y: dog.y + 0.4, aim: Math.PI } })
    tick()
    expect(dogState(ledger.store(dog.id), sim.time)).toBe("barking")
    tick({}, ticks(DEFAULT_DOG_TUNING.dogBeat * 2))
    expect(noises("bark").length).toBeGreaterThanOrEqual(2)
    expect(slot("ann").prompt?.kind).toBe("dog")
    tick({ ann: { interact: true } })
    expect(ledger.store(dog.id)?.counts.fed).toBeFalsy()
    hold(slot("ann"), "food", 1)
    tick({ ann: { interact: true } })
    expect(ledger.store(dog.id)?.counts.fed).toBe(1)
    expect(ledger.count("ann", "food")).toBe(0)
    const barks = noises("bark").length
    tick({}, ticks(3))
    expect(noises("bark").length).toBe(barks)
    expect(dogState(ledger.store(dog.id), sim.time)).toBe("fed")
  })

  test("a fed dog's quiet runs out; then it barks at the dead but not at its friend", () => {
    const { sim, tick, ledger, slot, hold } = room({ ann: { x: dog.x + dog.chain + 0.6, y: dog.y + 0.4, aim: Math.PI } }, { dogHushTime: 1 })
    hold(slot("ann"), "food", 1)
    tick()
    tick({ ann: { interact: true } })
    expect(ledger.store(dog.id)?.counts.fed).toBe(1)
    tick({}, ticks(1.2))
    expect(dogState(ledger.store(dog.id), sim.time)).toBe("quiet")
    sim.ai.spawnZombie(sim.town, dog.x + 5, dog.y + 2, "wander")
    tick()
    expect(dogState(ledger.store(dog.id), sim.time)).toBe("barking")
  })

  test("the dead at it long enough kill it", () => {
    const { sim, tick, ledger } = room({ ann: { x: 30, y: 40, aim: 0 } }, { dogKillTime: 1 })
    const z = sim.ai.spawnZombie(sim.town, dog.x + 1.5, dog.y, "wander")
    z.speedScale = 0
    tick({}, ticks(1.4))
    expect(Math.hypot(z.x - dog.x, z.y - dog.y)).toBeLessThan(dog.chain + 0.9)
    expect(dogState(ledger.store(dog.id), sim.time)).toBe("dead")
  })
})

import { describe, expect, test } from "bun:test"
import { labUrl } from "./lab-url"
import { catalogueHash, catalogueLights, devRoute, filterAssets, gameLink, hubCommands, hubGames, hubPath, hubTargets, parseHubHash } from "./dev-hub-model"

const router = JSON.stringify({ games: ["getaway", "blackout", "outbreak", "carrier"], workers: false })

describe("developer hub", () => {
  test("navigation stays relative to each game prefix; the Lab is its own app", () => {
    for (const host of ["getaway", "blackout"]) for (const command of hubCommands) {
      const expected = command.id === "lab" ? "/arcade/lab/" : `/arcade/${host}/`
      expect(new URL(command.href, `https://anoma.ly/arcade/${host}/dev.html`).pathname).toStartWith(expected)
      expect(new URL(command.href, `http://arcade.localhost:1355/arcade/${host}/dev.html`).pathname).toStartWith(expected)
    }
  })
  test("prototypes remain separate", () => {
    expect(hubGames.map(game => game.id).sort()).toEqual(["blackout", "carrier", "getaway", "outbreak", "wings"])
    expect(hubGames.filter(game => game.prototype).map(game => game.id)).toEqual(["carrier", "outbreak"])
  })
  test("router pages link mounted games on this origin and fall back to production for the rest", () => {
    const targets = hubTargets("/arcade/getaway/dev.html", router)
    expect(targets).toEqual({ kind: "router", local: ["getaway", "blackout", "outbreak", "carrier"], workers: false })
    for (const id of ["getaway", "blackout", "outbreak", "carrier"]) expect(gameLink(id, targets)).toEqual({ href: `/arcade/${id}/`, source: "local" })
    expect(gameLink("wings", targets)).toEqual({ href: "https://anoma.ly/arcade/wings/", source: "production" })
  })
  test("production pages link same-origin siblings; standalone servers link production", () => {
    expect(gameLink("blackout", hubTargets("/arcade/getaway/dev.html", null))).toEqual({ href: "/arcade/blackout/", source: "production" })
    expect(gameLink("blackout", hubTargets("/dev.html", null))).toEqual({ href: "https://anoma.ly/arcade/blackout/", source: "production" })
    for (const meta of ["", "not json", "{}", '{"games":"getaway"}']) expect(hubTargets("/dev.html", meta).kind).toBe("standalone")
  })
  test("router paths mirror production prefixes", () => {
    const mounted = ["getaway", "blackout"]
    expect(devRoute("/", mounted)).toEqual({ kind: "redirect", location: hubPath })
    expect(devRoute("/arcade/", mounted)).toEqual({ kind: "redirect", location: hubPath })
    expect(devRoute("/arcade/blackout?practice", mounted)).toEqual({ kind: "redirect", location: "/arcade/blackout/?practice" })
    expect(devRoute("/arcade/blackout/?practice", mounted)).toEqual({ kind: "vite", game: "blackout", path: "/?practice" })
    expect(devRoute("/arcade/getaway/@vite/client", mounted)).toEqual({ kind: "vite", game: "getaway", path: "/@vite/client" })
    expect(devRoute("/arcade/getaway/audio-assets/a.mp3", mounted)).toEqual({ kind: "vite", game: "getaway", path: "/audio-assets/a.mp3" })
    for (const path of ["/arcade/getaway/api/quick", "/arcade/getaway/ws/ABCD", "/arcade/getaway/ws", "/arcade/getaway/ws?room=A"]) expect(devRoute(path, mounted)).toEqual({ kind: "worker", game: "getaway" })
    expect(devRoute("/arcade/getaway/wsx.ts", mounted).kind).toBe("vite")
    for (const path of ["/arcade/wings/", "/arcade/landing", "/src/main.ts", "/arcade/../etc"]) expect(devRoute(path, mounted).kind).not.toBe("vite")
  })
  test("old per-game Lab pages redirect to the single Lab with that game chosen", () => {
    const mounted = ["getaway", "blackout", "outbreak", "lab"]
    expect(devRoute("/arcade/getaway/lab.html", mounted)).toEqual({ kind: "redirect", location: "/arcade/lab/?game=getaway" })
    expect(devRoute("/arcade/outbreak/lab.html?section=outbreak-vignette&game=x", mounted)).toEqual({ kind: "redirect", location: "/arcade/lab/?game=outbreak&section=outbreak-vignette" })
    expect(devRoute("/arcade/lab/?game=blackout", mounted)).toEqual({ kind: "vite", game: "lab", path: "/?game=blackout" })
    expect(labUrl("https://anoma.ly/arcade/blackout/lab.html?bench", "blackout")).toBe("https://anoma.ly/arcade/lab/?game=blackout&bench=")
  })
  test("catalogue selection round-trips through the hash", () => {
    for (const id of ["getaway:compact", "getaway:prop:cone", "blackout:soldier"]) expect(parseHubHash(catalogueHash(id))).toEqual({ page: "catalogue", assetId: id })
    expect(parseHubHash("#catalogue")).toEqual({ page: "catalogue", assetId: undefined })
    expect(parseHubHash("#games").page).toBe("games")
    expect(parseHubHash("").page).toBe("games")
    expect(parseHubHash("#catalogue/%E0").page).toBe("catalogue")
  })
  test("ID, label and category search intersect", () => {
    const assets = [{ id: "getaway:compact", label: "Compact", category: "vehicle" as const }, { id: "getaway:prop:cone", label: "Cone", category: "prop" as const }]
    expect(filterAssets(assets, "GETAWAY compact", "vehicle").map(asset => asset.id)).toEqual(["getaway:compact"])
    expect(filterAssets(assets, "compact", "prop")).toEqual([])
    expect(filterAssets(assets, "", "all")).toHaveLength(2)
  })
  test("lighting setups are distinct finite recipes", () => {
    expect(Object.keys(catalogueLights)).toEqual(["neutral", "day", "night", "interior"])
    expect(new Set(Object.values(catalogueLights).map(recipe => JSON.stringify(recipe))).size).toBe(4)
    for (const recipe of Object.values(catalogueLights)) expect(Number.isFinite(recipe.moonPower)).toBe(true)
  })
})

