import { GasClouds } from "../src/specials/gas"
import { featureRoom } from "./coop-feature-room"

for (const seat of [0, 1]) for (const rule of SPECIAL_RULES) test(`seat ${seat}: ${rule.id} seed, health and response survive full/delta snapshots and late join`, () => {
  const r = featureRoom()
  try {
    const actor = r.clients[seat]!
    r.place(actor, 30, 46)
    const z = spawnSpecial(r.core.sim, rule.kind, 33, 46, Math.PI)!
    r.tick(12)
    const check = () => {
      r.flush()
      for (const c of r.clients) {
        const remote = c.snapHistory.get(c.lastServerTick)!.zombies.find((a) => a.id === z.id)!
        expect(remote).toBeDefined()
        expect(specialKindOf(remote.seed)).toBe(rule.kind)
        expect(remote.hp).toBe(Math.round(z.hp))
        expect(remote.state).toBe(z.state)
        const drawn = c.view.zombies.find((a) => a.id === z.id)!
        expect(drawn.seed).toBe(z.seed)
        expect(drawn.hp).toBe(remote.hp)
      }
    }
    check()
    const hp = z.hp
    r.act(actor, { fire: true })
    r.tick(12)
    expect(z.hp).toBeLessThan(hp)
    check()
    r.join()
    r.tick(12)
    check()
  } finally { r.close() }
})

test("host and teammate kills: active and late clients receive the room's damaging gas", () => {
  const r = featureRoom()
  try {
    for (const actor of [r.a, r.b]) {
      r.place(actor, 30, 46)
      const z = spawnSpecial(r.core.sim, SPECIAL_BLOATER, 33, 46)!
      // One pistol hit kills; seed/kind and authoritative death rules remain real.
      z.hp = 1
      z.speedScale = 0
      r.tick(12)
      r.act(actor, { fire: true })
      r.tick(12)
      expect(z.state).toBe("dead")
      expect(specialsOf(r.core.sim).clouds.length).toBeGreaterThan(0)
      r.flush()
      for (const c of r.clients) expect(specialsOf(c.sim).clouds).toEqual(specialsOf(r.core.sim).clouds.map(gasOnWire))
    }
    r.join()
    r.tick(12)
    r.flush()
    const clouds = specialsOf(r.core.sim).clouds.map(gasOnWire)
    const draw = (source: typeof clouds) => {
      const gas = new GasClouds()
      gas.sync(source, r.core.sim.time)
      const sprites = new Float32Array(64 * SPRITE_FLOATS)
      const count = gas.draw(sprites, 0, r.core.sim.time, () => 0)
      expect(count).toBeGreaterThan(0)
      return sprites.slice(0, count * SPRITE_FLOATS)
    }
    const expectedSprites = draw(clouds)
    for (const c of r.clients) {
      expect(specialsOf(c.sim).clouds).toEqual(clouds)
      expect(draw(specialsOf(c.sim).clouds)).toEqual(expectedSprites)
    }
  } finally { r.close() }
})

import { describe, expect, test } from "bun:test"
import {
  canSpawnZombieAt,
  coopChaserScale,
  coopPopulationScale,
  DEFAULT_AI_CONFIG,
  DEFAULT_PACING_TUNING,
  initialSpawnCount,
  isInsideSafeZone,
  isSpawnBehindPlayer,
  isSpawnInView,
  LEGACY_AI_CONFIG,
  pacingControls,
  STARTING_SAFEHOUSE_RECT,
} from "../shared/ai"
import { TICK_DT } from "../shared/clock"
import { CoopSim, SPAWN_POINTS } from "../shared/coop-sim"
import { dayCycle } from "../shared/day-cycle"
import { coopCurve, DEFAULT_COOP_SCALING } from "../shared/night-ramp/coop"
import { coopNoiseShare, coopSpawnClearance, NIGHTFALL_HOUR, openingClockActive, openingThreat, TODAY_COOP } from "../shared/pacing"
import { sightRects } from "../shared/map"
import { LocalSession } from "../shared/session"
import { createOutbreakSettings, setOutbreakSetting } from "../src/settings"

describe("Outbreak first-night opening pacing & spawn rules", () => {
  test("Pacing group Lab controls cover all PacingTuning keys with explicit ranges, steps, units and defaults", () => {
    expect(pacingControls.map((c) => String(c.key)).sort()).toEqual(Object.keys(DEFAULT_PACING_TUNING).sort())
    for (const control of pacingControls) {
      expect(control.group).toBe("Pacing")
      const def = DEFAULT_PACING_TUNING[control.key as keyof typeof DEFAULT_PACING_TUNING]
      expect(def).toBeGreaterThanOrEqual(control.min)
      expect(def).toBeLessThanOrEqual(control.max)
      expect(typeof control.unit).toBe("string")
    }

    const settings = createOutbreakSettings()
    expect(settings.ai.startHour).toBe(17.5)
    expect(settings.ai.openingClock).toBe(0.25)
    expect(settings.dayCycle.hour).toBe(17.5)
    // D-22 Balanced Curve
    expect(settings.ai.safeRadius).toBe(17)
    expect(settings.ai.initialDensity).toBe(0.1)
    expect(settings.ai.rampTime).toBe(405)
    expect(settings.ai.noiseSensitivity).toBe(1.05)
    expect(settings.ai.maxActiveNearPlayer).toBe(3)

    setOutbreakSetting(settings, "safeRadius", 26)
    setOutbreakSetting(settings, "pacing.maxActiveNearPlayer", 6)
    expect(settings.ai.safeRadius).toBe(26)
    expect(settings.ai.maxActiveNearPlayer).toBe(6)
  })

  test("starting at 17:30 dusk opens in the Noir palette, and the workbench is lit by daylight at first and the flashlight after", () => {
    const session = new LocalSession(7)
    expect(session.view.hour).toBe(17.5)
    expect(dayCycle(session.view.hour).darkness).toBeGreaterThan(0.75)
    const T = session.sim.progression.tuning
    const benchLightAtStart = session.sim.progression.benchLight("bench:ash", session.view.hour, [])
    expect(benchLightAtStart).toBeGreaterThanOrEqual(T.researchLight)
    // About 35 s in (17:48) the route reaches the bench: daylight alone is too dim, the flashlight (on by default) makes up the rest
    const bench = session.sim.progression.benches.find((b) => b.id === "bench:ash")!.bench
    const atBench = { x: bench.x - 0.85, y: bench.y, flashlightOn: true, flashlightOutput: 1 }
    expect(session.sim.progression.benchLight("bench:ash", 17.8, [])).toBeLessThan(T.researchLight)
    expect(session.sim.progression.benchLight("bench:ash", 17.8, [atBench])).toBeGreaterThanOrEqual(T.researchLight)
  })

  test("the opening clock makes nightfall take about a minute of real time, then the clock runs at normal speed, solo and co-op", () => {
    for (const players of [1, 4]) {
      const sim = new CoopSim(7, 7, 0.22)
      for (let i = 0; i < players; i++) sim.addSurvivor(i === 0 ? "player" : `p${i}`, i)
      let nightfallAt: number | null = null
      for (let tick = 1; tick <= 90 * 60; tick++) {
        sim.stepWorld(TICK_DT, 120)
        if (nightfallAt === null && sim.hour >= NIGHTFALL_HOUR) nightfallAt = tick * TICK_DT
      }
      expect(nightfallAt).not.toBeNull()
      expect(nightfallAt!).toBeGreaterThan(55)
      expect(nightfallAt!).toBeLessThan(65)
      // After nightfall the remaining ~30 s ran at the normal 120x: 2 game minutes per real second
      expect(sim.hour).toBeCloseTo(NIGHTFALL_HOUR + ((90 - nightfallAt!) * 120) / 3600, 1)
      expect(sim.elapsedHours).toBeCloseTo(sim.hour - 17.5, 6)
    }
    // The next evening runs at the normal speed, and the legacy unpaced mode never slows the clock
    expect(openingClockActive(1, 17.5, 0)).toBe(true)
    expect(openingClockActive(1, 17.5, 24)).toBe(false)
    expect(openingClockActive(0, 17.5, 0)).toBe(false)
    expect(openingClockActive(1, 18.5, 0.5)).toBe(false)
  })

  test("the opening calm eases dusk threat in over the first 50 s, like the 16:00 start did, and leaves unpaced mode alone", () => {
    const paced = { directorPacing: 1, openingCalm: DEFAULT_PACING_TUNING.openingCalm }
    const duskThreat = dayCycle(17.5).threat
    expect(openingThreat(duskThreat, 0, paced)).toBe(0)
    expect(openingThreat(duskThreat, 30, paced)).toBeGreaterThan(0.3)
    expect(openingThreat(duskThreat, 30, paced)).toBeLessThan(0.6)
    expect(openingThreat(duskThreat, 50, paced)).toBeCloseTo(duskThreat, 6)
    expect(openingThreat(duskThreat, 0, { directorPacing: 0, openingCalm: 50 })).toBe(duskThreat)
    // 30 s into the old 16:00 start the clock read 17:00, whose threat sits in the same band
    expect(dayCycle(17).threat).toBeGreaterThan(0.3)
    expect(dayCycle(17).threat).toBeLessThan(0.6)
  })

  test("opening spawn clears safeRadius around spawn and Ash House, spaces out sparse shamblers, and never spawns in view or behind player", () => {
    // D-22 defaults (10% of 16 = 2 shamblers) and the denser pre-D-22 opening (25% of 28 = 7), which saved presets still load.
    for (const [config, expected] of [[DEFAULT_AI_CONFIG, 2], [LEGACY_AI_CONFIG, 7]] as const) {
      const session = new LocalSession(7, 7, 0.22, config)
      const p = session.view.player
      const town = session.view.town
      const blockers = sightRects(town)
      const zombies = session.view.zombies

      expect(zombies.length).toBe(initialSpawnCount(config.zombieCount, config.initialDensity, 1, 1))
      expect(zombies.length).toBe(expected)

      const [sx0, sy0, sx1, sy1] = STARTING_SAFEHOUSE_RECT
      for (const z of zombies) {
        expect(z.state).toBe("wander")
        expect(z.awareness).toBe(0)
        const dist = Math.hypot(z.x - p.x, z.y - p.y)
        expect(dist).toBeGreaterThanOrEqual(config.safeRadius)
        // Never inside Ash House
        const inAsh = z.x >= sx0 && z.x <= sx1 && z.y >= sy0 && z.y <= sy1
        expect(inAsh).toBe(false)
        // Never in initial sight cone or flashlight beam
        expect(isSpawnInView(z.x, z.y, [p], blockers)).toBe(false)
      }

      // Check pairwise spacing of initial zombies (spaced out, not clumped)
      for (let i = 0; i < zombies.length; i++) {
        for (let j = i + 1; j < zombies.length; j++) {
          const d = Math.hypot(zombies[i]!.x - zombies[j]!.x, zombies[i]!.y - zombies[j]!.y)
          expect(d).toBeGreaterThanOrEqual(8.0)
        }
      }
    }
  })

  test("canSpawnZombieAt enforces safeRadius, sight cone, close awareness, flashlight cone, and rear-hemisphere exclusions", () => {
    const session = new LocalSession(7, 7, 0.22, { zombieCount: 0 })
    const town = session.view.town
    const nav = session.ai.nav
    const blockers = sightRects(town)
    const survivor = { x: 44, y: 44, aim: 0, flashlightOn: true, flashlightOutput: 1 } // At crossroads facing East (0)

    // 1. Inside safeRadius (10 m < 20 m) -> rejected
    expect(
      canSpawnZombieAt(54, 44, town, nav, [survivor], blockers, { safeRadius: 20 }),
    ).toBe(false)

    // 2. Outside safeRadius (24 m East) but directly in unobstructed sight cone -> rejected
    expect(isSpawnInView(68, 44, [survivor], blockers)).toBe(true)
    expect(
      canSpawnZombieAt(68, 44, town, nav, [survivor], blockers, { safeRadius: 20, forbidInView: true }),
    ).toBe(false)

    // 3. Right behind player (15 m West along street, aim = 0) -> rejected by behind-player rule even if safeRadius is smaller
    expect(isSpawnBehindPlayer(29, 44, [survivor], 20)).toBe(true)
    expect(
      canSpawnZombieAt(29, 44, town, nav, [survivor], blockers, { safeRadius: 10, forbidBehind: true, behindDist: 20 }),
    ).toBe(false)

    // 4. Inside starting safehouse (Ash House [22..37, 24..35.5]) -> rejected
    expect(isInsideSafeZone(28, 30, [survivor], 20)).toBe(true)

    // 5. Valid backstage point (26 m North-East behind Hardware Store wall at (64, 20), occluded from (44, 44) and outside rear arc) -> accepted
    expect(isSpawnInView(64, 20, [survivor], blockers)).toBe(false)
    expect(isSpawnBehindPlayer(64, 20, [survivor], 20)).toBe(false)
    expect(
      canSpawnZombieAt(64, 20, town, nav, [survivor], blockers, { safeRadius: 20, forbidInView: true, forbidBehind: true }),
    ).toBe(true)
  })

  test("director stages a 1–3 zombie first encounter after exploration, ramps with time/noise/distance/threat, and caps simultaneous chasers", () => {
    const session = new LocalSession(7)
    const p = session.view.player

    // First 30 s: player explores inside Ash House and searches containers; 0 chasers
    Object.assign(p, { x: 27.7, y: 31.5, aim: -Math.PI / 2 })
    for (let i = 0; i < 30 * 60; i++) {
      const angle = (i / 60) * 0.5
      session.update(TICK_DT, { mx: Math.cos(angle) * 0.5, my: Math.sin(angle) * 0.5, aim: angle, interact: false }, 120)
    }
    expect(session.ai.pacing.telemetry.activeChasers).toBe(0)
    expect(session.ai.pacing.firstEncounterStage).toBe("grace")

    // Advance past 45 s so first encounter triggers (1–3 investigating scouts)
    Object.assign(p, { x: 29.5, y: 41.0, aim: 0 })
    for (let i = 0; i < 20 * 60; i++) {
      session.update(TICK_DT, { mx: 0.2, my: 0, aim: 0, interact: false }, 120)
    }
    expect(["staged", "completed"]).toContain(session.ai.pacing.firstEncounterStage)
    const engagedEarly = session.view.zombies.filter(
      (z) => z.state === "investigate" || z.state === "alert" || z.state === "chase",
    )
    expect(engagedEarly.length).toBeGreaterThanOrEqual(1)
    expect(engagedEarly.length).toBeLessThanOrEqual(3)

    // Even if 12 zombies are alerted at once by loud noise, active chasers never exceed effectiveMaxActive
    for (const z of session.view.zombies) {
      z.state = "chase"
      z.awareness = 1
      z.targetX = p.x
      z.targetY = p.y
    }
    session.update(TICK_DT, { mx: 0, my: 0, aim: 0, interact: false }, 120)
    const chasersAfterCap = session.view.zombies.filter(
      (z) => z.state === "chase" || z.state === "alert" || z.state === "bash",
    ).length
    expect(chasersAfterCap).toBeLessThanOrEqual(session.ai.pacing.telemetry.effectiveMaxActive)
    expect(chasersAfterCap).toBeLessThanOrEqual(DEFAULT_AI_CONFIG.maxActiveNearPlayer)
  })

  test("co-op scales opening count, target population, and active chaser cap by survivor count (1 vs 4 players)", () => {
    const soloSim = new CoopSim(7)
    const soloSlot = soloSim.addSurvivor("p0", 0)
    soloSim.stepSurvivor(soloSlot, { mx: 0, my: 0, aim: -Math.PI / 2, interact: false }, TICK_DT)
    soloSim.stepWorld(TICK_DT, 120)

    const coopSim = new CoopSim(7)
    const coopSlots = SPAWN_POINTS.map((_, idx) => coopSim.addSurvivor(`p${idx}`, idx))
    for (const slot of coopSlots) {
      coopSim.stepSurvivor(slot, { mx: 0, my: 0, aim: -Math.PI / 2, interact: false }, TICK_DT)
    }
    coopSim.stepWorld(TICK_DT, 120)

    expect(coopPopulationScale(4)).toBeCloseTo(2.05, 4)
    expect(coopChaserScale(4)).toBeCloseTo(2.8, 4)
    expect(coopSim.ai.agents.length).toBeGreaterThan(soloSim.ai.agents.length)
    expect(coopSim.ai.pacing.telemetry.desiredPopulation).toBeGreaterThan(soloSim.ai.pacing.telemetry.desiredPopulation)

    // Advance both to late night (t = 400 s, hour = 23) and compare effectiveMaxActive and desiredPopulation
    soloSim.time = 400
    soloSim.hour = 23
    soloSim.stepWorld(TICK_DT, 120)

    coopSim.time = 400
    coopSim.hour = 23
    coopSim.stepWorld(TICK_DT, 120)

    expect(coopSim.ai.pacing.telemetry.desiredPopulation).toBeGreaterThan(soloSim.ai.pacing.telemetry.desiredPopulation)
    // Still Night 1 for the night ramp: Gentle Start holds six survivors to a chaser more than the solo hold (AR-92).
    const soloCap = soloSim.ai.pacing.telemetry.effectiveMaxActive
    expect(coopSim.ai.pacing.telemetry.effectiveMaxActive).toBeGreaterThan(soloCap)
    expect(coopSim.ai.pacing.telemetry.effectiveMaxActive).toBeLessThanOrEqual(soloCap + 2)
  })

  test("co-op scaling is sub-linear by default, Today is linear, and one survivor plays the same either way (AR-92)", () => {
    const curve = coopCurve(DEFAULT_COOP_SCALING)
    const today = coopCurve({ ...DEFAULT_COOP_SCALING, coopScaleMode: 0 })
    expect(today).toEqual(TODAY_COOP)
    for (const c of [curve, today]) {
      expect(coopPopulationScale(1, c)).toBe(1)
      expect(coopChaserScale(1, c)).toBe(1)
      expect(coopNoiseShare(1, c)).toBe(1)
    }
    expect(coopPopulationScale(4, today)).toBeCloseTo(2.05, 4)
    expect(coopChaserScale(6, today)).toBeCloseTo(4, 4)
    // Each extra survivor adds less than the one before.
    const pop = [1, 2, 3, 4, 5, 6].map((n) => coopPopulationScale(n, curve))
    for (let i = 2; i < pop.length; i++) expect(pop[i]! - pop[i - 1]!).toBeLessThan(pop[i - 1]! - pop[i - 2]! + 1e-9)
    expect(pop[3]!).toBeLessThan(coopPopulationScale(4, today))
    expect(pop[5]!).toBeLessThan(2.1)
    expect(coopChaserScale(6, curve)).toBeLessThan(2.6)
    // Six survivors' gunfire heats the director like fewer than four shooters, not six.
    expect(coopNoiseShare(6, curve)).toBeGreaterThan(3)
    expect(coopSpawnClearance(curve, 4)).toBeGreaterThanOrEqual(20)
    expect(coopSpawnClearance(curve, 1)).toBe(0)
    expect(coopSpawnClearance(today, 4)).toBe(0)
  })
})

import { describe, expect, test } from "bun:test"
import { TICK_DT } from "../shared/clock"
import { CoopSim } from "../shared/coop-sim"
import { pinStoreId, readPin, recipeFillsIn, recipeWaitsOnPart } from "../shared/discovery/recipes"
import { RECIPES } from "../shared/progression"
import { LocalSession, type Command } from "../shared/session"

const CRAFT = (seconds: number) => Math.ceil(seconds / TICK_DT) + 2

function setup(hour = 12) {
  const session = new LocalSession(7, 7, 0.22, { zombieCount: 0 })
  session.sim.hour = hour
  const progression = session.sim.progression
  const ledger = progression.ledger
  const p = session.view.player
  const bench = progression.benches.find((b) => b.id === "bench:ash")!
  const step = (cmd: Partial<Command> = {}, n = 1) => {
    for (let i = 0; i < n; i++) session.update(TICK_DT, { mx: 0, my: 0, aim: p.aim, interact: false, ...cmd }, 0)
  }
  const give = (item: string, count = 1) => expect(ledger.apply({ kind: "grant", actor: "player", item, count }).ok).toBe(true)
  const install = (part: string) => expect(ledger.apply({ kind: "grant", actor: "player", item: part, store: bench.id }).ok).toBe(true)
  const notices = () => session.view.notices.splice(0).map((n) => n.text)
  const atBench = () => {
    Object.assign(p, { x: bench.bench.x - 0.85, y: bench.bench.y, aim: 0 })
    session.rebuildCollision()
    step()
  }
  const make = (recipe: string) => step({ pick: { mode: "craft", index: progression.craftable().findIndex((r) => r.id === recipe) } })
  return { session, progression, ledger, p, bench, step, give, install, notices, atBench, make }
}

describe("recipe board rules", () => {
  const recipe = (id: string) => RECIPES.find((r) => r.id === id)!
  const has = (...items: string[]) => (item: string) => items.includes(item)

  test("a recipe fills in once each of its materials has been picked up and its part installed", () => {
    expect(recipeFillsIn(recipe("bandage"), has("chem"), has())).toBe(true)
    expect(recipeFillsIn(recipe("lure"), has("scrap"), has())).toBe(false)
    expect(recipeFillsIn(recipe("lure"), has("scrap", "battery"), has())).toBe(true)
    expect(recipeFillsIn(recipe("reinforced"), has("scrap"), has())).toBe(false)
    expect(recipeWaitsOnPart(recipe("reinforced"), has("scrap"), has())).toBe(true)
    expect(recipeFillsIn(recipe("reinforced"), has("scrap"), has("toolbox"))).toBe(true)
    expect(recipeFillsIn(recipe("battery"), has("scrap", "chem"), has("toolbox"))).toBe(false)
    expect(recipeFillsIn(recipe("battery"), has("scrap", "chem"), has("car-battery"))).toBe(true)
    // The can tripwire is only learned by taking one down.
    expect(recipeFillsIn(recipe("tripwire"), has("scrap", "plank", "chem", "battery"), has("toolbox", "car-battery"))).toBe(false)
  })
})

describe("the recipe board in play", () => {
  test("picking up a material fills in what it feeds, with a brass pin and no notice", () => {
    const { progression, ledger, step, give, notices } = setup()
    step()
    // The survivor starts with planks, which make nothing on their own.
    expect(progression.board.corkboard()).toEqual({ learned: [], ideas: [] })
    give("chem")
    step()
    expect(progression.board.corkboard()).toEqual({ learned: ["bandage"], ideas: [] })
    give("scrap")
    step()
    // Scrap and chem are both in (a pouch too): reinforcing waits on the toolbox and batteries on the generator.
    expect(progression.board.corkboard()).toEqual({ learned: ["bandage", "spiked-board", "pouch"], ideas: ["reinforced", "battery"] })
    expect(readPin(ledger.store(pinStoreId("spiked-board")), "spiked-board")).toMatchObject({ seat: null, source: "sketch" })
    expect(notices().filter((t) => /learn|recipe/i.test(t))).toEqual([])
  })

  test("installing the toolbox and the generator fills in what waits on them", () => {
    const { progression, step, give, install } = setup()
    give("scrap")
    give("chem")
    step()
    install("toolbox")
    step()
    expect(progression.learned("reinforced")).toBe(true)
    expect(progression.learned("battery")).toBe(false)
    install("car-battery")
    step()
    expect(progression.learned("battery")).toBe(true)
  })

  test("a page still teaches early and pins as the finder's", () => {
    const { session, progression, ledger, p, step } = setup()
    const page = progression.knowledge.pages.find((x) => x.buildingId === "pharmacy")!
    Object.assign(p, { x: page.x, y: page.y + 1, aim: -Math.PI / 2 })
    session.rebuildCollision()
    step({}, 2)
    step({ interact: true })
    step({}, 2)
    expect(progression.learned(page.recipe)).toBe(true)
    expect(readPin(ledger.store(pinStoreId(page.recipe)), page.recipe)).toMatchObject({ actor: "player", seat: 0, source: "chart" })
  })

  test("the bench's E opens its board: no tinkering, no materials used", () => {
    const { session, ledger, step, give, atBench } = setup()
    give("chem", 2)
    atBench()
    expect(session.view.prompt).toMatchObject({ kind: "bench", primary: { id: "board", label: "Recipes" } })
    step({ interact: true })
    step({}, 4)
    expect(ledger.count("player", "chem")).toBe(2)
    expect(session.view.player.channel).toBeNull()
  })

  test("carrying a part, E at the bench installs it", () => {
    const { session, ledger, bench, step, give, atBench } = setup()
    give("toolbox")
    atBench()
    expect(session.view.prompt?.primary.id).toBe("install")
    step({ interact: true })
    step({}, 2)
    expect(ledger.count(bench.id, "toolbox")).toBe(1)
  })
})

describe("making things", () => {
  test("a bandage is made anywhere", () => {
    const { progression, ledger, step, give, make } = setup()
    give("chem", 2)
    step()
    make("bandage")
    step({}, CRAFT(progression.tuning.craftTime))
    expect(ledger.count("player", "bandage")).toBe(1)
  })

  test("a spiked board is made only at a workbench, and only in light", () => {
    const { session, progression, ledger, p, step, give, notices, atBench, make } = setup(23)
    give("scrap", 2)
    step()
    expect(progression.learned("spiked-board")).toBe(true)
    notices()
    make("spiked-board")
    step()
    expect(notices()).toContain("At a workbench")
    p.flashlightOn = false
    atBench()
    make("spiked-board")
    step()
    expect(notices()).toContain("Too dark")
    session.sim.hour = 12
    make("spiked-board")
    step({}, CRAFT(progression.tuning.craftTime))
