type SessionLike = { sim: OutbreakSim; view: { player: { x: number; y: number; aim: number } } }

const gas = new GasClouds()

/** Spawns a special `distance` metres ahead of the survivor (offline sessions only). */
function spawnAhead(session: SessionLike, kindId: string, distance = 5) {
  const kind = specialKindFromId(kindId)
  if (kind === 0) return { error: `unknown kind "${kindId}" (${SPECIAL_KIND_IDS.join(", ")})` }
  const p = session.view.player
  const x = p.x + Math.cos(p.aim) * distance
  const y = p.y + Math.sin(p.aim) * distance
  const a = spawnSpecial(session.sim, kind, x, y, p.aim + Math.PI)
  if (!a) return { error: "no free Lab zombie id" }
  return { kind: kindId, id: a.id, x: a.x, y: a.y, hp: a.hp }
}

function summary(sim: OutbreakSim) {
  const st = specialsOf(sim)
  const counts = specialCounts(sim)
  const alive: Record<string, number> = {}
  for (const rule of SPECIAL_RULES) alive[rule.id] = counts[rule.kind] ?? 0
  return { alive, night: st.night, shrieks: st.shrieks, bursts: st.bursts, clouds: st.clouds.length }
}

/** Special zombies (shared/specials): Lab › Specials (rarity, stats, spawn buttons) and `arcade cmd specials.spawn`. */
export const outbreakSpecialsFeature = registerOutbreakClientFeature({
  id: "specials",
  order: 17,
  netSession: {
    onApplyWorld: (net, shared) => {
      specialsOf(net.sim).clouds = (shared.specials?.clouds ?? []).map((c) => ({ ...c }))
      return false
    },
  },
  settingsGroup: { subsystem: "specials", defaults: DEFAULT_SPECIALS_TUNING },
  labControls: (host): LabControl[] => [
    ...(specialsControls as readonly LabControl[]),
    ...SPECIAL_RULES.map(
      (rule): LabControl => ({
        key: `spawnSpecial.${rule.id}`,
        label: `Spawn ${rule.label} ahead`,
        group: "Specials",
        type: "action",
        run: () => {
          if (!host.progressionHost.offline()) return
          spawnAhead(host.session(), rule.id)
        },
      }),
    ),
  ],
  gameCommands: (host): LabCommand[] => [
    {
      id: "specials.spawn",
      label: "Spawn Special Zombie",
      shortLabel: "Special",
      category: "Scene",
      undoable: false,
      args: {
        kind: { type: "string", description: `Kind (${SPECIAL_KIND_IDS.join(", ")})` },
        distance: { type: "number", description: "Metres ahead of the survivor (default 5)" },
      },
      enabled: () => !host.coop.net,
      run: async (_ctx, args) => {
        const out = spawnAhead(host.session(), String(args?.kind ?? "brute"), Number(args?.distance ?? 5))
        await host.harness().step(1 / 60)
        return out
      },
    },
  ],
  harnessMethods: (host) => ({
    /** Spawns a special (`runner`, `brute`, `screamer`, `bloater`, `riot`, `lurker`) `distance` m ahead. */
    spawnSpecial(kind: string, distance = 5) {
      return spawnAhead(host.session(), kind, distance)
    },
  }),
  harnessState: (host) => ({ specials: { ...summary(host.session().sim), gasDrawn: gas.clouds.length } }),
  feel: {
    reset: () => gas.reset(),
    processFrame: ({ session, addSprites, addCount }) => {
      const { town, time } = session.view
      gas.sync(specialsOf(session.sim).clouds, time)
      return gas.draw(addSprites, addCount, time, (x, y) => supportHeight(town, x, y))
    },
  },
})

import type { AIState } from "../../shared/ai"
import type { CombatMeleeEvent, CombatShotEvent } from "../../shared/combat"
import type { Town } from "../../shared/map"
import {
  DEFAULT_SPECIALS_TUNING,
  hitFromFront,
  specialKindOf,
  SPECIAL_BLOATER,
  SPECIAL_BRUTE,
  SPECIAL_LURKER,
  SPECIAL_NONE,
  SPECIAL_RIOT,
  SPECIAL_SCREAMER,
} from "../../shared/specials/kinds"
import { surfaceAt, zombieStepEvent } from "./space"
import type { SoundEvent } from "./types"

export type SpecialSoundZombie = { id: number; x: number; y: number; state: AIState; seed?: number; aim?: number }

export const SPECIAL_SOUND_TUNING = {
  /** A shriek carries this far (m); the rest of the specials' sounds stop at `hearing`. */
  shriekHearing: 60,
  hearing: 22,
  /** Seconds between a Bloater's gurgles, and between a walking Brute's footfalls. */
  gurgleEvery: 3.2,
  bruteStep: 0.62,
}

type Memory = { state: AIState; x: number; y: number; next: number }

/**
 * Sounds for special zombies, from state changes only (no wire fields), so co-op peers hear the same: the Screamer's
 * shriek (its alert is always a shriek), a Bloater's gurgle and wet burst, a Brute's heavy footfalls, a sleeping
 * Lurker's hiss as it wakes, and bullets or blows ringing off a Riot cop's shield. Library samples, re-pitched.
 */
export class SpecialSounds {
  readonly tuning = { ...SPECIAL_SOUND_TUNING }
  private readonly memory = new Map<number, Memory>()
  private readonly heardShots = new Set<number>()
  private readonly heardHits = new Set<string>()
  private lastTime = 0

  reset(): void {
    this.memory.clear()
    this.heardShots.clear()
    this.heardHits.clear()
    this.lastTime = 0
  }

  observe(
    zombies: readonly SpecialSoundZombie[],
    shots: readonly CombatShotEvent[],
    meleeSwings: readonly CombatMeleeEvent[] | undefined,
    time: number,
    listener: { x: number; y: number },
    emit: (e: SoundEvent) => void,
    rng: () => number,
    town?: Town,
  ): void {
    const t = this.tuning
    const dt = Math.max(0, Math.min(0.25, time - this.lastTime))
    this.lastTime = time
    const dist = (x: number, y: number) => Math.hypot(x - listener.x, y - listener.y)
    const seen = new Set<number>()
    const byId = new Map<number, SpecialSoundZombie>()
    for (const z of zombies) {
      const kind = specialKindOf(z.seed ?? 0)
      if (kind === SPECIAL_NONE) continue
      seen.add(z.id)
      byId.set(z.id, z)
      const prev = this.memory.get(z.id)
      const m: Memory = prev ?? { state: z.state, x: z.x, y: z.y, next: time + rng() * 2 }
      const d = dist(z.x, z.y)
      const at = { x: z.x, y: z.y, source: "zombie" }
      if (prev && prev.state !== z.state) {
        if (kind === SPECIAL_SCREAMER && z.state === "alert" && d <= t.shriekHearing) {
          emit({ id: "zombie.alert", ...at, rate: 1.55, gain: 1.15, cutoffHz: 4200, priority: 92 })
          emit({ id: "zombie.alert", ...at, rate: 1.36, gain: 0.85, cutoffHz: 3600, delay: 0.26, priority: 90 })
          emit({ id: "zombie.alert", ...at, rate: 1.22, gain: 0.72, cutoffHz: 3200, delay: 0.56, priority: 88 })
        } else if (kind === SPECIAL_BLOATER && z.state === "dead" && d <= t.shriekHearing) {
          emit({ id: "zombie.hit", ...at, rate: 0.5, gain: 1.15, cutoffHz: 1800, priority: 88 })
          emit({ id: "zombie.death", ...at, rate: 0.78, gain: 0.95, delay: 0.04, priority: 85 })
          emit({ id: "melee.hit.blade", ...at, rate: 0.84, gain: 0.85, delay: 0.09, priority: 85 })
        } else if (kind === SPECIAL_LURKER && prev.state === "wander" && z.state !== "dead" && d <= t.hearing) {
          emit({ id: "zombie.alert", ...at, rate: 0.84, gain: 1.1, priority: 85 })
        }
      }
      if (z.state !== "dead" && d <= t.hearing) {
        if (kind === SPECIAL_BLOATER && time >= m.next) {
          m.next = time + t.gurgleEvery * (0.75 + rng() * 0.5)
          emit({ id: "zombie.groan.idle", ...at, rate: 0.76 + rng() * 0.06, gain: 0.72, cutoffHz: 1400 })
        } else if (kind === SPECIAL_BRUTE && dt > 0) {
          const speed = Math.hypot(z.x - m.x, z.y - m.y) / dt
          if (speed > 0.35 && time >= m.next) {
            m.next = time + t.bruteStep * Math.max(0.6, Math.min(1.4, 1.6 / Math.max(0.6, speed)))
            const surf = town ? surfaceAt(town, z.x, z.y) : "concrete"
            emit(zombieStepEvent(surf, "brute", z.x, z.y, speed, rng))
          }
        }
      }
      m.state = z.state
      m.x = z.x
      m.y = z.y
      this.memory.set(z.id, m)
    }
    for (const id of this.memory.keys()) if (!seen.has(id)) this.memory.delete(id)

    // Bullets and blows that land on a Riot cop's shield ring off it.
    const arc = DEFAULT_SPECIALS_TUNING.riotArc
    for (const shot of shots) {
      if (this.heardShots.has(shot.id) || shot.hitZombieId === null) continue
      this.heardShots.add(shot.id)
      const z = byId.get(shot.hitZombieId)
      if (!z || specialKindOf(z.seed ?? 0) !== SPECIAL_RIOT || z.aim === undefined) continue
      if (hitFromFront(z.x, z.y, z.aim, shot.fromX, shot.fromY, arc)) emit({ id: "impact.bullet.metal", x: shot.toX, y: shot.toY, gain: 1.15, source: "shot" })
    }
    if (this.heardShots.size > 128) this.heardShots.clear()
    for (const m of meleeSwings ?? []) {
      for (const h of m.hits) {
        const key = `${m.id}:${h.zombieId}`
        if (this.heardHits.has(key)) continue
        this.heardHits.add(key)
        const z = byId.get(h.zombieId)
        if (!z || specialKindOf(z.seed ?? 0) !== SPECIAL_RIOT || z.aim === undefined) continue
        if (hitFromFront(z.x, z.y, z.aim, m.x, m.y, arc)) emit({ id: "melee.hit.metal", x: h.x, y: h.y, gain: 1.1, rate: 0.85, source: m.attackerId })
      }
    }
    if (this.heardHits.size > 256) this.heardHits.clear()
  }
}

import type { OutbreakNetSectionCodec } from "../feature-registry"
import type { SpecialsState } from "./specials"
import type { GasCloud, SpecialsSnapshot } from "./net-types"

export const SEC_SPECIALS = 1024
const cm = (v: number) => Math.round(v * 100)
export const gasOnWire = (c: GasCloud): GasCloud => ({
  id: c.id, x: cm(c.x) / 100, y: cm(c.y) / 100,
  born: Math.fround(c.born), until: Math.fround(c.until), radius: cm(c.radius) / 100,
})

/** Send persistent hazards, not inferred deaths: a corpse can stream out before its gas expires. */
export const specialsNetSection: OutbreakNetSectionCodec<SpecialsState, SpecialsSnapshot> = {
  bit: SEC_SPECIALS,
  key: "specials",
  collect: ({ sim, state, viewerCenter, bubbleCx, bubbleCy, interest, isDelta, baseSnap }) => {
    const clouds = state.clouds.filter((c) => c.until > sim.time && (!viewerCenter ||
      (Math.abs(c.x - bubbleCx) <= interest.bubbleHalfExtent + c.radius &&
       Math.abs(c.y - bubbleCy) <= interest.bubbleHalfExtent + c.radius))).map(gasOnWire)
    const value = clouds.length ? { clouds } : undefined
    const base = isDelta ? baseSnap?.specials : undefined
    return { snapshotValue: value, shouldWrite: JSON.stringify(value) !== JSON.stringify(base), writePayload: value ?? { clouds: [] } }
  },
  encode: (w, value) => {
    w.uvar(value.clouds.length)
    for (const c of value.clouds) w.uvar(c.id).i32(cm(c.x)).i32(cm(c.y)).f32(c.born).f32(c.until).u16(cm(c.radius))
  },
  decode: (r) => {
    const clouds: GasCloud[] = []
    for (let n = r.uvar(), i = 0; i < n; i++) clouds.push({ id: r.uvar(), x: r.i32() / 100, y: r.i32() / 100, born: r.f32(), until: r.f32(), radius: r.u16() / 100 })
    return clouds.length ? { clouds } : undefined
  },
  decodeOmitted: ({ isDelta, baseSnap }) => isDelta ? baseSnap?.specials : undefined,
}

import { SPRITE_FLOATS } from "@arcade/kit/gpu/renderer"
import type { GasCloud } from "../../shared/specials/net-types"

/** A burst Bloater's authoritative cloud: where, when, how big and for how long. */
export type GasPuff = { id: number; x: number; y: number; born: number; radius: number; life: number }

/**
 * The Bloater's gas, drawn from the room's persistent clouds as a sickly ground stain and slow drifting puffs. The sim
 * owns the damage (`shared/specials/specials.ts`).
 */
export class GasClouds {
  readonly clouds: GasPuff[] = []

  reset(): void {
    this.clouds.length = 0
  }

  /** Both offline and co-op draw the hazard itself, even if nobody saw the Bloater die. */
  sync(clouds: readonly GasCloud[], time: number): void {
    this.clouds.length = 0
    for (const c of clouds) {
      if (c.until > time) this.clouds.push({ id: c.id, x: c.x, y: c.y, born: c.born, radius: c.radius, life: c.until - c.born })
    }
  }

  /** Writes the clouds into the additive sprite list from `count`; returns the new count. */
  draw(sprites: Float32Array, count: number, time: number, ground: (x: number, y: number) => number): number {
    const max = Math.floor(sprites.length / SPRITE_FLOATS)
    const put = (x: number, y: number, z: number, size: number, r: number, g: number, b: number, a: number, kind: number, rot: number) => {
      if (count >= max) return
      const o = count++ * SPRITE_FLOATS
      sprites[o] = x
      sprites[o + 1] = y
      sprites[o + 2] = z
      sprites[o + 3] = size
      sprites[o + 4] = r
      sprites[o + 5] = g
      sprites[o + 6] = b
      sprites[o + 7] = a
      sprites[o + 8] = kind
      sprites[o + 9] = rot
      sprites[o + 10] = 0
      sprites[o + 11] = 0
    }
    for (const c of this.clouds) {
      const age = time - c.born
      const u = age / Math.max(0.1, c.life)
      const fade = Math.min(1, age / 0.35) * Math.min(1, (1 - u) / 0.3)
      if (fade <= 0.01) continue
      const gy = ground(c.x, c.y)
      const swell = 0.75 + 0.25 * Math.min(1, age / 1.2)
      put(c.x, gy + 0.04, c.y, c.radius * swell, 0.2, 0.26, 0.04, 0.5 * fade, 6, 0)
      for (let k = 0; k < 7; k++) {
        const ang = k * 2.39996 + age * (0.12 + 0.03 * k)
        const d = c.radius * swell * (0.25 + 0.5 * ((k * 0.37) % 1))
        const lift = 0.35 + 0.25 * Math.sin(age * 0.8 + k)
        put(c.x + Math.cos(ang) * d, gy + lift, c.y + Math.sin(ang) * d, c.radius * 0.5, 0.3, 0.38, 0.06, 0.22 * fade, 0, 0)
      }
    }
    return count
  }
}

import { inRect, type Rect } from "@arcade/kit/sim/geom"
import { samplePointLightLevel, STARTING_SAFEHOUSE_RECT, zombieTraitsFromSeed, type AIAgent } from "../ai"
import type { ZombieHit, ZombieHitOutcome } from "../combat"
import { dayCycle } from "../day-cycle"
import { survivorDamage } from "../feature-registry"
import { flashlightAwarenessAt, type FlashlightTuning } from "../flashlight"
import { inBuildingFootprint, sightRects } from "../map"
import type { OutbreakSim } from "../sim-types"
import type { GasCloud } from "./net-types"
export type { GasCloud } from "./net-types"
import {
  DEFAULT_SPECIALS_TUNING,
  encodeSpecialSeed,
  hitFromFront,
  mix32,
  ordinarySeed,
  pickSpecialKind,
  specialAllowed,
  specialChance,
  specialKindOf,
  specialRolls,
  specialWeight,
  SPECIAL_BLOATER,
  SPECIAL_BRUTE,
  SPECIAL_LURKER,
  SPECIAL_NONE,
  SPECIAL_RIOT,
  SPECIAL_RUNNER,
  SPECIAL_SCREAMER,
  type SpecialKind,
  type SpecialPhase,
  type SpecialsTuning,
} from "./kinds"

/**
 * Special zombies in the simulation: which zombies become special as they appear, and what each kind does. Every
 * zombie is rolled once, the tick it appears (`classifySpecials`, run before and after the crowd steps so director
 * spawns are rolled before the snapshot that first carries them). All state is plain JSON in the feature state.
 */

/** What the sim remembers about one living special. */
export type SpecialRuntime = {
  kind: SpecialKind
  /** The seed it was made with; an agent with this id and another seed is a different zombie. */
  seed: number
  /** Its own speed and perception before its kind changed them. */
  baseSpeed: number
  basePerception: number
  /** Lurker: still asleep. */
  dormant: boolean
  /** Screamer: when the shriek in progress lands (0 when not shrieking), and when it may shriek again. */
  shriekUntil: number
  shriekReadyAt: number
  /** Bloater: its gas has been released. */
  burst: boolean
}

export type SpecialsState = {
  /** Seed each zombie id was rolled with. */
  seen: Record<number, number>
  live: Record<number, SpecialRuntime>
  clouds: GasCloud[]
  nextCloud: number
  /** Nights begun so far (1 during the first night), and whether it was dark last tick. */
  night: number
  wasDark: boolean
  /** Tuning as of the last step, for the hit rule. */
  tuning: SpecialsTuning
  /** Shrieks that landed and clouds released (harness and tests). */
  shrieks: number
  bursts: number
  lastPrune: number
}

export function createSpecialsState(hour = 17.5): SpecialsState {
  const dark = dayCycle(hour).darkness >= 0.5
  return {
    seen: {},
    live: {},
    clouds: [],
    nextCloud: 1,
    night: dark ? 1 : 0,
    wasDark: dark,
    tuning: DEFAULT_SPECIALS_TUNING,
    shrieks: 0,
    bursts: 0,
    lastPrune: 0,
  }
}

export function specialsOf(sim: OutbreakSim): SpecialsState {
  let st = sim.getFeatureState<SpecialsState>("specials")
  if (!st) {
    st = createSpecialsState(sim.hour)
    sim.featureStates.set("specials", st)
  }
  return st
}

export function specialPhase(sim: OutbreakSim, st: SpecialsState): SpecialPhase {
  return { darkness: dayCycle(sim.hour).darkness, night: st.night }
}

function trackNights(sim: OutbreakSim, st: SpecialsState): void {
  const dark = dayCycle(sim.hour).darkness >= 0.5
  if (dark && !st.wasDark) st.night++
  st.wasDark = dark
}

/** Police stations and cruisers: where riot cops come from. */
function nearPolice(sim: OutbreakSim, x: number, y: number, radius: number): boolean {
  const r2 = radius * radius
  for (const b of sim.town.buildings) {
    if (b.archetype !== "police") continue
    const cx = Math.max(b.rect[0], Math.min(b.rect[2], x))
    const cy = Math.max(b.rect[1], Math.min(b.rect[3], y))
    if ((cx - x) ** 2 + (cy - y) ** 2 <= r2) return true
  }
  for (const v of sim.vehicles.list) {
    if (v.kind === "cruiser" && (v.x - x) ** 2 + (v.y - y) ** 2 <= r2) return true
  }
  return false
}

function nearestSurvivorDist(sim: OutbreakSim, x: number, y: number): number {
  let best = Infinity
  for (const s of sim.slots) best = Math.min(best, Math.hypot(s.survivor.x - x, s.survivor.y - y))
  return best
}

/**
 * An unlit spot inside a building near `(x, y)`, out of every survivor's reach, for a Lurker to wait in; `null` when
 * there is none. Never the starting safehouse.
 */
export function darkRoomSpot(sim: OutbreakSim, x: number, y: number, t: SpecialsTuning, salt: number): { x: number; y: number } | null {
  const near = sim.town.buildings
    .map((b) => {
      const cx = Math.max(b.rect[0], Math.min(b.rect[2], x))
      const cy = Math.max(b.rect[1], Math.min(b.rect[3], y))
      return { b, d: Math.hypot(cx - x, cy - y) }
    })
    .filter((e) => e.d <= 40)
    .sort((a, b) => a.d - b.d || (a.b.id < b.b.id ? -1 : 1))
    .slice(0, 4)
  let h = salt >>> 0
  for (const { b } of near) {
    const [x0, y0, x1, y1] = b.rect
    for (let k = 0; k < 12; k++) {
      h = mix32((h + 0x9e3779b9) >>> 0)
      const px = x0 + 0.8 + ((h & 0xffff) / 65536) * Math.max(0, x1 - x0 - 1.6)
      const py = y0 + 0.8 + ((h >>> 16) / 65536) * Math.max(0, y1 - y0 - 1.6)
      if (!inBuildingFootprint(b, px, py) || inRect(px, py, STARTING_SAFEHOUSE_RECT)) continue
      if (!sim.ai.nav.walkable({ x: px, y: py })) continue
      if (nearestSurvivorDist(sim, px, py) < 10) continue
      if (samplePointLightLevel(sim.town, sim.hour, px, py) >= t.lurkerDark) continue
      return { x: px, y: py }
    }
  }
  return null
}

function setSeed(a: AIAgent, seed: number): void {
  a.seed = seed >>> 0
  const traits = zombieTraitsFromSeed(a.seed)
  a.hitReaction = traits.hitReaction
  a.deathVariant = traits.deathVariant
  a.toughness = traits.toughness
}

function kindHp(t: SpecialsTuning, kind: SpecialKind): number {
  switch (kind) {
    case SPECIAL_RUNNER:
      return t.runnerHp
    case SPECIAL_BRUTE:
      return t.bruteHp
    case SPECIAL_SCREAMER:
      return t.screamerHp
    case SPECIAL_BLOATER:
      return t.bloaterHp
    case SPECIAL_RIOT:
      return t.riotHp
    case SPECIAL_LURKER:
      return t.lurkerHp
    default:
      return 100
  }
}

function kindSpeed(t: SpecialsTuning, kind: SpecialKind): number {
  switch (kind) {
    case SPECIAL_BRUTE:
      return t.bruteSpeed
    case SPECIAL_BLOATER:
      return t.bloaterSpeed
    case SPECIAL_SCREAMER:
      return 0.9
    case SPECIAL_RIOT:
      return 0.9
    default:
      return 1
  }
}

/** Turns `a` into a special of `kind` (its seed carries the kind from now on) and starts tracking it. */
export function makeSpecial(st: SpecialsState, a: AIAgent, kind: Exclude<SpecialKind, 0>, t: SpecialsTuning): SpecialRuntime {
  setSeed(a, encodeSpecialSeed(a.seed, kind))
  a.toughness = 1
  a.hp = a.maxHp = kindHp(t, kind)
  const rt: SpecialRuntime = {
    kind,
    seed: a.seed,
    baseSpeed: a.speedScale,
    basePerception: a.perceptionScale,
    dormant: kind === SPECIAL_LURKER,
    shriekUntil: 0,
    shriekReadyAt: 0,
    burst: false,
  }
  a.speedScale = rt.baseSpeed * kindSpeed(t, kind)
  if (kind === SPECIAL_SCREAMER) a.perceptionScale = rt.basePerception * 1.3
  if (kind === SPECIAL_RUNNER) a.perceptionScale = rt.basePerception * 1.15
  if (kind === SPECIAL_BRUTE) a.aggression *= 1.15
  if (kind === SPECIAL_LURKER) {
    a.state = "wander"
    a.awareness = 0
    a.speedScale = 0
    a.perceptionScale = 0
  }
  st.live[a.id] = rt
  st.seen[a.id] = a.seed
  return rt
}

/** Rolls one zombie that has just appeared: special or not, and which kind. */
function classify(sim: OutbreakSim, st: SpecialsState, a: AIAgent, t: SpecialsTuning, phase: SpecialPhase, chance: number): void {
  const own = st.live[a.id]
  if (own && own.seed === a.seed) {
    st.seen[a.id] = a.seed
    return
  }
  if (own) delete st.live[a.id]
  const [u, v] = specialRolls(sim.town.seed, a.id, a.seed)
  let kind: SpecialKind = SPECIAL_NONE
  if (a.state !== "dead" && a.state !== "crawler" && u < chance) {
    const weights = [0, 0, 0, 0, 0, 0]
    for (let k = SPECIAL_RUNNER; k <= SPECIAL_LURKER; k++) {
      if (!specialAllowed(k as SpecialKind, phase)) continue
      let w = specialWeight(t, k as SpecialKind)
      if (k === SPECIAL_RIOT && !nearPolice(sim, a.x, a.y, t.riotPoliceRadius)) w *= t.riotStray
      weights[k - 1] = w
    }
    kind = pickSpecialKind(weights, v)
    if (kind === SPECIAL_LURKER) {
      const spot = darkRoomSpot(sim, a.x, a.y, t, a.seed ^ a.id)
      if (spot) {
        a.x = a.homeX = a.wanderX = spot.x
        a.y = a.homeY = a.wanderY = spot.y
        a.vx = a.vy = 0
        a.path = []
        a.hordeId = undefined
      } else {
        weights[SPECIAL_LURKER - 1] = 0
        kind = pickSpecialKind(weights, v)
      }
    }
  }
  if (kind !== SPECIAL_NONE) makeSpecial(st, a, kind, t)
  else {
    if (specialKindOf(a.seed) !== SPECIAL_NONE) setSeed(a, ordinarySeed(a.seed))
    st.seen[a.id] = a.seed
  }
}

/** Rolls every zombie not yet rolled. */
export function classifySpecials(sim: OutbreakSim, st: SpecialsState, t: SpecialsTuning): void {
  const phase = specialPhase(sim, st)
  const chance = specialChance(t, phase)
  for (const a of sim.ai.agents) {
    if (st.seen[a.id] !== a.seed) classify(sim, st, a, t, phase, chance)
  }
}

function prune(sim: OutbreakSim, st: SpecialsState): void {
  const ids = new Set<number>()
  for (const a of sim.ai.agents) ids.add(a.id)
  for (const k of Object.keys(st.seen)) if (!ids.has(Number(k))) delete st.seen[Number(k)]
  for (const k of Object.keys(st.live)) if (!ids.has(Number(k))) delete st.live[Number(k)]
}

function wakeLurker(a: AIAgent, rt: SpecialRuntime, t: SpecialsTuning, x: number, y: number): void {
  rt.dormant = false
  a.speedScale = rt.baseSpeed * t.lurkerSpeed
  a.perceptionScale = rt.basePerception * 1.2
  a.aggression *= 1.25
  a.awareness = 1
  a.targetX = x
  a.targetY = y
  a.targetKind = "sight"
  if (a.state === "wander" || a.state === "investigate" || a.state === "search") {
    a.state = "alert"
    a.stateTime = 0
    a.timer = 0.22
  }
}

/** The survivor whose light or nearness wakes a sleeping Lurker at `a`, if any. */
function lurkerWaker(
  sim: OutbreakSim,
  a: AIAgent,
  t: SpecialsTuning,
  blockers: readonly Rect[],
  flashlight: FlashlightTuning,
): { x: number; y: number } | null {
  for (const s of sim.slots) {
    const p = s.survivor
    if (Math.hypot(p.x - a.x, p.y - a.y) <= t.lurkerWakeNear) return p
    if (flashlightAwarenessAt(p, a.x, a.y, blockers, flashlight) > 0.05) return p
  }
  return null
}

function inCloud(c: GasCloud, x: number, y: number): boolean {
  return (x - c.x) ** 2 + (y - c.y) ** 2 <= c.radius * c.radius
}

function release(sim: OutbreakSim, st: SpecialsState, a: AIAgent, rt: SpecialRuntime, t: SpecialsTuning): void {
  rt.burst = true
  st.bursts++
  st.clouds.push({ id: st.nextCloud++, x: a.x, y: a.y, born: sim.time, until: sim.time + t.gasTime, radius: t.gasRadius })
  sim.ai.emitNoise(a.x, a.y, 9, "bloater", sim.time, `bloater-${a.id}`, 0.8)
}

/** Before the crowd steps: night count, rolls, Runners' sprint, Brutes' bashing, Lurkers waking, gas. */
export function stepSpecials(sim: OutbreakSim, st: SpecialsState, t: SpecialsTuning, dt: number, flashlight: FlashlightTuning): void {
  st.tuning = t
  trackNights(sim, st)
  if (sim.time - st.lastPrune > 2) {
    st.lastPrune = sim.time
    prune(sim, st)
  }
  classifySpecials(sim, st, t)
  const dark = dayCycle(sim.hour).darkness >= 0.5
  const aggr = sim.ai.config.aggression
  let blockers: Rect[] | null = null
  for (const a of sim.ai.agents) {
    const rt = st.live[a.id]
    if (!rt || rt.seed !== a.seed) continue
    switch (rt.kind) {
      case SPECIAL_RUNNER: {
        const hunting = a.state === "chase" || a.state === "alert"
        a.speedScale = rt.baseSpeed * (hunting && dark ? t.runnerSprint : t.runnerDaySpeed)
        break
      }
      case SPECIAL_BRUTE:
        if (a.state === "bash") a.timer -= dt * a.aggression * aggr * Math.max(0, t.bruteBash - 1)
        break
      case SPECIAL_SCREAMER:
        if (rt.shriekUntil > 0) {
          if (a.state !== "alert") {
            // Staggered, knocked down or killed mid-shriek: it never lands, and it needs a moment to try again.
            rt.shriekUntil = 0
            rt.shriekReadyAt = sim.time + 2.5
          } else if (sim.time >= rt.shriekUntil) {
            rt.shriekUntil = 0
            rt.shriekReadyAt = sim.time + t.shriekCooldown
            st.shrieks++
            sim.ai.emitNoise(a.x, a.y, t.shriekRadius, "shriek", sim.time, `shriek-${a.id}`, 2.4)
            a.timer = 0
          } else {
            a.timer = Math.max(a.timer, rt.shriekUntil - sim.time + dt)
          }
        }
        break
      case SPECIAL_BLOATER:
        if (a.state === "dead" && !rt.burst) release(sim, st, a, rt, t)
        break
      case SPECIAL_LURKER:
        if (rt.dormant) {
          blockers ??= sightRects(sim.town)
          const by = a.state === "wander" ? lurkerWaker(sim, a, t, blockers, flashlight) : { x: a.targetX, y: a.targetY }
          if (by) wakeLurker(a, rt, t, by.x, by.y)
          else {
            a.speedScale = 0
            a.perceptionScale = 0
            a.awareness = 0
            a.vx = a.vy = 0
          }
        }
        break
    }
  }
  stepGas(sim, st, t, dt)
}

function stepGas(sim: OutbreakSim, st: SpecialsState, t: SpecialsTuning, dt: number): void {
  if (st.clouds.length === 0) return
  st.clouds = st.clouds.filter((c) => c.until > sim.time)
  for (const c of st.clouds) {
    for (const s of sim.slots) {
      const p = s.survivor
      if (p.vehicleId || !inCloud(c, p.x, p.y)) continue
      const damage = survivorDamage(sim, s, t.gasDamage * dt, "environment")
      // Shielded entirely (the escaped): no choking either.
      if (damage <= 0 && t.gasDamage > 0) continue
      p.health = Math.max(0, p.health - damage)
      p.stamina = Math.max(0, p.stamina - t.gasStamina * dt)
      p.regenCooldown = Math.max(p.regenCooldown, 0.5)
    }
    for (const a of sim.ai.agents) {
      if (a.state === "dead" || !inCloud(c, a.x, a.y)) continue
      a.hp = Math.max(0, a.hp - t.gasZombieDamage * dt)
      if (a.hp <= 0) {
        a.state = "dead"
        a.stateTime = 0
        a.lastHitBy = "gas"
      }
    }
  }
}

/** After the crowd steps: roll director spawns, start shrieks, keep gas slowing zombies, burst bloaters. */
export function stepSpecialsLate(sim: OutbreakSim, st: SpecialsState, t: SpecialsTuning, dt: number): void {
  classifySpecials(sim, st, t)
  for (const a of sim.ai.agents) {
    const rt = st.live[a.id]
    if (rt && rt.seed === a.seed) {
      if (rt.kind === SPECIAL_SCREAMER && rt.shriekUntil === 0 && (a.state === "alert" || a.state === "chase")) {
        if (a.seesTarget && sim.time >= rt.shriekReadyAt) startShriek(sim, a, rt, t)
        else if (a.state === "alert") {
          // On the wire a Screamer's alert always means a shriek, so it skips the ordinary snarl.
          a.state = "chase"
          a.stateTime = 0
          a.repathAt = 0
        }
      } else if (rt.kind === SPECIAL_BLOATER && a.state === "dead" && !rt.burst) release(sim, st, a, rt, t)
      else if (rt.kind === SPECIAL_LURKER && rt.dormant && a.state !== "wander") wakeLurker(a, rt, t, a.targetX, a.targetY)
    }
    if (st.clouds.length > 0 && a.state !== "dead") {
      for (const c of st.clouds) {
        if (!inCloud(c, a.x, a.y)) continue
        const keep = Math.max(0, Math.min(1, t.gasSlow))
        a.x -= a.vx * dt * (1 - keep)
        a.y -= a.vy * dt * (1 - keep)
        break
      }
    }
  }
}

function startShriek(sim: OutbreakSim, a: AIAgent, rt: SpecialRuntime, t: SpecialsTuning): void {
  rt.shriekUntil = sim.time + t.shriekTime
  a.state = "alert"
  a.stateTime = 0
  a.timer = t.shriekTime + 0.05
  a.vx = a.vy = 0
}

/**
 * How a hit lands on a special: a Riot cop's shield soaks the front and stops shoves; a Brute shrugs off shoves, light
 * swings and bullets (it still takes the damage); a sleeping Lurker wakes. Reads the kind from the seed, so co-op
 * prediction agrees with the room.
 */
export function specialHitOutcome(sim: OutbreakSim, z: AIAgent, hit: ZombieHit): ZombieHitOutcome | null {
  const kind = specialKindOf(z.seed)
  if (kind === SPECIAL_NONE) return null
  const st = sim.getFeatureState<SpecialsState>("specials")
  const t = st?.tuning ?? DEFAULT_SPECIALS_TUNING
  if (kind === SPECIAL_BRUTE) {
    if (hit.kind === "shove" || (hit.kind === "melee" && !hit.heavy) || hit.kind === "shot") return { damage: hit.damage, react: false }
    return null
  }
  if (kind === SPECIAL_RIOT) {
    if (!hitFromFront(z.x, z.y, z.aim, hit.fromX, hit.fromY, t.riotArc)) return null
    if (hit.kind === "shove") return { damage: 0, react: false }
    return { damage: hit.damage * Math.max(0, t.riotFront), react: false }
  }
  if (kind === SPECIAL_LURKER) {
    const rt = st?.live[z.id]
    if (rt && rt.seed === z.seed && rt.dormant) wakeLurker(z, rt, t, hit.fromX, hit.fromY)
  }
  return null
}

/** Ids the Lab spawns specials with: above every chunk's id range and below the hordes'. */
const LAB_ID_BASE = 60240
const LAB_ID_END = 60410

/** Lab: a special of `kind` at `(x, y)` facing `aim`, or `null` when there is no room for one. */
export function spawnSpecial(sim: OutbreakSim, kind: Exclude<SpecialKind, 0>, x: number, y: number, aim = 0): AIAgent | null {
  const st = specialsOf(sim)
  const used = new Set(sim.ai.agents.map((a) => a.id))
  let id = -1
  for (let k = LAB_ID_BASE; k <= LAB_ID_END; k++) {
    if (!used.has(k)) {
      id = k
      break
    }
  }
  if (id < 0) return null
  const a = sim.ai.spawnZombie(sim.town, x, y, "wander", aim)
  a.id = id
  makeSpecial(st, a, kind, st.tuning)
  return a
}

/** Counts of living specials by kind (harness). */
export function specialCounts(sim: OutbreakSim): Record<string, number> {
  const out: Record<string, number> = {}
  for (const a of sim.ai.agents) {
    if (a.state === "dead") continue
    const k = specialKindOf(a.seed)
    if (k !== SPECIAL_NONE) out[k] = (out[k] ?? 0) + 1
  }
  return out
}

import { MAT, Mesh } from "@arcade/kit/gpu/mesh"
import { INST_FLOATS, type Batch, type Renderer } from "@arcade/kit/gpu/renderer"
import { clamp } from "@arcade/kit/rig"
import {
  SPECIAL_BLOATER,
  SPECIAL_BRUTE,
  SPECIAL_LURKER,
  SPECIAL_RIOT,
  SPECIAL_RUNNER,
  SPECIAL_SCREAMER,
  type SpecialKind,
} from "../../shared/specials/kinds"
import { hex } from "../level"

/**
 * How each special zombie reads inside the blocky Former Townsfolk figure: a body scale, a posture, a palette and a few
 * bone-attached accessories (helmet and shield, swollen belly, hanging jaw, broad shoulders, glowing eyes). The crowd
 * renderer (`src/zombies.ts`) asks `specialLook` per zombie and draws the accessories through `SpecialAccessories`.
 */
export type SpecialLook = {
  /** Whole-body scale about the feet. */
  scale: number
  /** Extra forward pitch of the torso (rad; negative leans back) standing, and moving at full speed. */
  hunch: number
  runHunch: number
  /** How far the hips drop (m). */
  crouch: number
  /** Cloth/skin colours (sRGB) for the refined look: trousers, shirt, skin. */
  trousers: number
  shirt: number
  skin: number
  /** Accessories, by `ACCESSORIES` index. */
  parts: readonly number[]
}

const BIB = 0
const HELMET = 1
const SHIELD = 2
const SHOULDERS = 3
const BELLY = 4
const JAW = 5
const EYES = 6

/** Which bone each accessory rides: 1 torso, 2 head. */
const ACCESSORY_BONE = [1, 2, 1, 1, 1, 2, 2] as const

export const SPECIAL_LOOKS: Readonly<Record<Exclude<SpecialKind, 0>, SpecialLook>> = {
  [SPECIAL_RUNNER]: { scale: 0.96, hunch: 0.08, runHunch: 0.34, crouch: 0, trousers: 0x23262b, shirt: 0x9c3326, skin: 0x9aa18b, parts: [BIB] },
  [SPECIAL_BRUTE]: { scale: 1.28, hunch: 0.14, runHunch: 0.2, crouch: 0.02, trousers: 0x3a3934, shirt: 0x55603f, skin: 0x7b8364, parts: [SHOULDERS] },
  [SPECIAL_SCREAMER]: { scale: 1.0, hunch: 0.02, runHunch: 0.12, crouch: 0, trousers: 0x9a9c90, shirt: 0xb5b6ab, skin: 0xb3baa6, parts: [JAW] },
  [SPECIAL_BLOATER]: { scale: 1.1, hunch: -0.1, runHunch: -0.06, crouch: 0.03, trousers: 0x4a4434, shirt: 0x8f8a58, skin: 0xa3a65e, parts: [BELLY] },
  [SPECIAL_RIOT]: { scale: 1.04, hunch: 0.1, runHunch: 0.18, crouch: 0.02, trousers: 0x1b2230, shirt: 0x1f2a3a, skin: 0x7c8670, parts: [HELMET, SHIELD] },
  [SPECIAL_LURKER]: { scale: 1.0, hunch: 0.62, runHunch: 0.5, crouch: 0.17, trousers: 0x121314, shirt: 0x151617, skin: 0x5d6158, parts: [EYES] },
}

export function specialLook(kind: SpecialKind): SpecialLook | null {
  return kind === 0 ? null : SPECIAL_LOOKS[kind]
}

const linear = (h: number): [number, number, number] => hex(h).map((c) => c ** 2.2) as [number, number, number]
const paletteCache = new Map<number, Float32Array>()

/** Writes a special's palette over the zombie's own (`out` is the renderer's 9 × rgb part tint). */
export function applySpecialPalette(kind: SpecialKind, out: Float32Array): void {
  const look = specialLook(kind)
  if (!look) return
  let p = paletteCache.get(kind)
  if (!p) {
    const t = linear(look.trousers)
    const s = linear(look.shirt)
    const k = linear(look.skin)
    p = new Float32Array([...t, ...s, ...k, ...s, ...k, ...t, ...t, 1, 1, 1, 1, 1, 1])
    paletteCache.set(kind, p)
  }
  out.set(p)
}

/** The extra forward torso pitch for a special moving at `speed` m/s (shrieking Screamers rear back). */
export function specialHunch(kind: SpecialKind, speed: number, state: string): number {
  const look = specialLook(kind)
  if (!look) return 0
  if (kind === SPECIAL_SCREAMER && state === "alert") return -0.5
  const u = clamp(speed / 3.5, 0, 1)
  return look.hunch + (look.runHunch - look.hunch) * u
}

/** How far the head tips back (rad, world pitch): enough to keep a hunched face up; a shrieking Screamer throws it back. */
export function specialHeadLift(kind: SpecialKind, hunch: number, state: string): number {
  if (kind === SPECIAL_SCREAMER && state === "alert") return 0.75
  return hunch * 0.55
}

/** A sleeping Lurker sits lower than an awake one. */
export function specialCrouch(kind: SpecialKind, state: string): number {
  const look = specialLook(kind)
  if (!look) return 0
  return kind === SPECIAL_LURKER && state !== "wander" ? look.crouch * 0.4 : look.crouch
}

/** Bone-local accessory meshes (x forward, y up the bone, z to the side), sized to the Former Townsfolk torso and head. */
function buildAccessories(): Mesh[] {
  const A = MAT.actor
  const bib = new Mesh()
  bib.box(0.15, 0.17, -0.085, 0.163, 0.34, 0.085, hex(0xd8d3c2), A)
  bib.box(0.163, 0.23, -0.04, 0.167, 0.28, 0.04, hex(0x2a2a2a), A)

  const navy = hex(0x1c2432)
  const helmet = new Mesh()
  helmet.bevelBox(-0.095, 0.1, -0.112, 0.135, 0.27, 0.112, 0.035, navy, hex(0x26324a), A)
  helmet.box(0.118, 0.01, -0.1, 0.152, 0.16, 0.1, hex(0x46586c), MAT.glass)
  helmet.box(-0.115, -0.01, -0.1, -0.075, 0.13, 0.1, navy, A)

  const shield = new Mesh()
  const poly = hex(0x29323e)
  shield.box(0.25, -0.44, -0.27, 0.295, 0.6, 0.27, poly, A)
  shield.box(0.295, 0.32, -0.2, 0.3, 0.46, 0.2, hex(0x50627a), MAT.glass)
  shield.box(0.295, 0.08, -0.25, 0.302, 0.15, 0.25, hex(0xb9c1ca), A)

  const shoulders = new Mesh()
  const olive = hex(0x4c5639)
  shoulders.bevelBox(-0.2, 0.28, -0.31, 0.14, 0.53, 0.31, 0.05, olive, hex(0x5a6545), A)
  shoulders.bevelBox(-0.25, 0.08, -0.19, -0.1, 0.5, 0.19, 0.04, olive, olive, A)

  const belly = new Mesh()
  const sick = hex(0x9da15a)
  belly.bevelBox(0.04, -0.02, -0.25, 0.34, 0.4, 0.25, 0.07, sick, hex(0xaeb267), A)
  belly.bevelBox(-0.2, 0.02, -0.29, 0.12, 0.34, 0.29, 0.06, sick, sick, A)
  for (const [y, z] of [
    [0.28, -0.1],
    [0.14, 0.12],
    [0.06, -0.04],
  ] as const) {
    belly.box(0.335, y, z - 0.03, 0.352, y + 0.05, z + 0.03, hex(0xd6dc6c), MAT.glow, 0.35)
  }

  const jaw = new Mesh()
  jaw.box(0.104, -0.02, -0.055, 0.124, 0.05, 0.055, hex(0x2b0f0f), A)
  jaw.box(0.04, -0.15, -0.062, 0.135, -0.015, 0.062, hex(0xa9b19c), A)
  jaw.box(-0.095, -0.22, -0.1, -0.055, 0.2, 0.1, hex(0x2b2621), A)
  for (const z of [-1, 1]) jaw.box(-0.06, -0.14, z * 0.095 - 0.012, 0.05, 0.17, z * 0.095 + 0.012, hex(0x2b2621), A)

  const eyes = new Mesh()
  for (const z of [-0.04, 0.04]) eyes.box(0.112, 0.088, z - 0.019, 0.126, 0.118, z + 0.019, hex(0xffb347), MAT.glow, 1.0)
  return [bib, helmet, shield, shoulders, belly, jaw, eyes]
}

const MAX_PER_ACCESSORY = 256

/** Instanced accessory batches for the crowd renderer, refilled every frame. */
export class SpecialAccessories {
  private readonly batches: Batch[]
  private readonly out: Batch[] = []

  constructor(renderer: Pick<Renderer, "addModel">) {
    this.batches = buildAccessories().map((m) => ({
      model: renderer.addModel(m),
      data: new Float32Array(MAX_PER_ACCESSORY * INST_FLOATS),
      count: 0,
    }))
  }

  begin(): void {
    for (const b of this.batches) b.count = 0
  }

  /**
   * Adds `kind`'s accessories for one zombie from its bone frames (`bones` at `bOff`, 12 floats a bone: p, x, y, z),
   * scaled by `scale` about `(ox, oy, oz)`. `hiddenMask` skips accessories on a lost head.
   */
  emit(
    kind: SpecialKind,
    bones: Float32Array,
    bOff: number,
    hiddenMask: number,
    scale: number,
    ox: number,
    oy: number,
    oz: number,
    shade: number,
    flash: number,
    alpha: number,
  ): void {
    const look = specialLook(kind)
    if (!look) return
    for (const part of look.parts) {
      const bone = ACCESSORY_BONE[part as 0]
      if ((hiddenMask & (1 << bone)) !== 0) continue
      const batch = this.batches[part]!
      if (batch.count >= MAX_PER_ACCESSORY) continue
      const f = bOff + bone * 12
      const xy = bones[f + 4]!
      const p = Math.asin(clamp(xy, -1, 1))
      const c = Math.cos(p)
      const yaw = c > 1e-4 ? Math.atan2(bones[f + 5]!, bones[f + 3]!) : Math.atan2(-bones[f + 9]!, bones[f + 11]!)
      const r = c > 1e-4 ? Math.atan2(-bones[f + 10]!, bones[f + 7]!) : 0
      const o = batch.count++ * INST_FLOATS
      const d = batch.data
      d[o] = ox + (bones[f]! - ox) * scale
      d[o + 1] = oy + (bones[f + 1]! - oy) * scale
      d[o + 2] = oz + (bones[f + 2]! - oz) * scale
      d[o + 3] = yaw
      d[o + 4] = shade
      d[o + 5] = shade
      d[o + 6] = shade
      d[o + 7] = scale
      d[o + 8] = p
      d[o + 9] = r
      d[o + 10] = alpha
      d[o + 11] = flash
    }
  }

  collect(): readonly Batch[] {
    this.out.length = 0
    for (const b of this.batches) if (b.count > 0) this.out.push(b)
    return this.out
  }
}

/** Accessory meshes as built, for tests (`[bib, helmet, shield, shoulders, belly, jaw, eyes]`). */
export function specialAccessoryMeshes(): Mesh[] {
  return buildAccessories()
}

import { expect, test } from "bun:test"
import type { Vision } from "../shared/vision"
import { LocalSession } from "../shared/session"
import { CoopView } from "../src/coop-view"

test("remote survivor churn reuses uploaded models for every seat and variant", () => {
  let uploads = 0
  const session = new LocalSession(7, 7, 0.22, { zombieCount: 0 })
  const slots = [0, 1, 2, 3].map((index) => ({ ...session.slot, id: `peer-${index}`, index }))
  const net = { remotes: slots, variantOfSeat: (index: number) => index }
  // Exercise the production body lifecycle without constructing its DOM lobby or GPU device.
  const view: CoopView = Object.assign(Object.create(CoopView.prototype), {
    renderer: { addModel: () => uploads++ }, net, avatars: new Map(), avatarCache: new Map(),
    hidden: () => false,
  })
  const vision = { visible: () => true } as unknown as Vision
  const draw = () => view.bodies(1 / 60, 0, session.sim.town, vision)
  for (let round = 0; round < 4; round++) {
    net.variantOfSeat = (index) => (index + round) % 4
    expect(draw().length).toBeGreaterThan(0)
  }
  const warmed = uploads
  expect(warmed).toBeGreaterThan(0)
  for (let round = 0; round < 12; round++) {
    net.remotes = []
    expect(draw()).toHaveLength(0)
    net.remotes = slots
    net.variantOfSeat = (index) => (index + round) % 4
    expect(draw().length).toBeGreaterThan(0)
  }
  expect(uploads).toBe(warmed)
})

